programs.sol:
"""Local punctuation and code-boundary features.

Positive rules cover quoted markup endings, parentheses after quotations,
SQL value lists and a few code transitions. JSON object values, dollar-variable
substitutions and attribute expressions have negative rules. Ordinary text
usually gets zero; arbitrary first-token effects are left unexplained.

State is the previous token and 128 trailing characters, reset per document.
Fixed rule amplitudes are shrunk by 10% to allow for their contextual variation.
"""

import unicodedata

READS = ()
FORM_ATTRIBUTES = {'name', 'value', 'id', 'alt', 'readonly'}
LINK_ATTRIBUTES = {'href', 'src'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, s, s[-128:]), 0.0
    p, recent = carry[1:]
    t, q = s.strip(), p.rstrip()
    syntax = t.replace('\\"', '"')
    last = q[-1:]
    quoted = bool(last) and (last in '"」』》' or
                             unicodedata.category(last) == 'Pf')
    value = 0.0

    # Quoted markup values, including quote and angle bracket in one token.
    if '">' in syntax:
        value = 4.0 if t.endswith('\\') else 2.5
    elif t.startswith(('"/>', '" />')):
        value = 2.7
    elif t.startswith('/>'):
        value = 4.0 if t.endswith('\\') else (3.0 if '\n' in s else 1.2)
    elif t == '>' or t.startswith('>\n'):
        value = 0.2 if '\n' in s else 0.0
        if s.startswith(' ') and '\n' in s:
            value = 6.0 if recent.rstrip().endswith('"') else 0.6
        if q.strip() == 'readonly':
            value = 4.2
    elif t == '="':
        value = 0.1
    elif t == 'script' and q.endswith('</'):
        value = 2.7

    if any(c + '(' in s for c in '"”’»」』》'):
        value = 2.7
    if quoted:
        if t.startswith(('(', '（')):
            value = 1.8
        elif t.startswith('['):
            value = 0.4
        elif t == '.':
            value = -0.6
        elif t == 'x':
            value = 0.6
        elif t in {'is', 'was', 'were', 'are', 'said', 'says'}:
            value = 0.1
    # Markup and string formatting use ASCII quotes, not navigation arrows.
    if q.endswith('"'):
        if t in FORM_ATTRIBUTES and s.startswith(' '):
            value = 4.0
        elif t in LINK_ATTRIBUTES and s.startswith(' '):
            value = 1.6 if t == 'href' else 2.8
        elif t == 'type' and s.startswith(' '):
            value = 3.0
        elif t in {'class', 'fill', 'content', 'xmlns'} and s.startswith(' '):
            value = 2.2
        elif t == '%':
            value = 3.0
    elif q.endswith("'") and t.startswith('('):
        value = 0.5
    elif q.endswith('`') and t.startswith('('):
        value = 0.15
    if (p.isspace() and recent.rstrip().endswith('"') and
            t in FORM_ATTRIBUTES):
        value = 4.0
    if s.startswith(' ') and recent.rstrip().endswith(('<input', '<script', '<img')):
        if t in FORM_ATTRIBUTES or t in LINK_ATTRIBUTES or t == 'placeholder':
            value = 3.5 if t == 'src' else 2.1

    # Exiting a statement or block; SQL's value-list introducer is strongest.
    if t == 'break':
        value = 1.8 if p.isspace() or q.endswith((';', '}')) else 0.2
    elif t.upper() == 'VALUES':
        query = recent.upper()
        if 'INSERT' in query and 'INTO' in query:
            value = 8.1
    elif t == 'WHERE':
        value = 0.45 if s.startswith(' ') else 1.0
    elif q.endswith('}'):
        if t == 'while':
            value = 3.4
        elif t == 'from':
            value = 1.2

    if t.startswith('?>'):
        value = 1.7
    if t.startswith('{{$'):
        value = -2.0
    elif t.startswith('="{{'):
        value = -1.2
    elif t.startswith('={') and q and q[-1].isalnum():
        if not q.lstrip().startswith('on'):
            value = -0.9
    elif s.startswith('":{"'):
        value = -0.6
    elif t in {'`', '``', '```'}:
        value = -0.04
    elif '\x00' in s:
        value = -0.14
    return (doc, s, (recent + s)[-128:]), 0.9 * value

programs.haiku:
"""Sketch v6: families of markup, SQL and JSX tokens; tracks whether we are inside an HTML start tag."""
import re

READS = ()
QUOTE_END = ('"', "”", "’", '\\"')
TAG_CLOSE = re.compile(r'"\s*/?>|\\">|"></|"><|\(\)">')
ATTR_NAME = re.compile(r"^\s[a-zA-Z][\w-]*$")
SQL_STRONG = {"VALUES": 6.0, "REFERENCES": 1.8}
SQL_WEAK = {"WHERE", "FROM"}

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    word = cur.strip()
    prev = toks[-2] if len(toks) > 1 else ""
    new_doc = len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    in_tag = False if new_doc else bool(carry)
    after_quote = prev.endswith(QUOTE_END)
    if new_doc:
        value = -0.2
    elif word and set(word) == {"·"}:
        value = -0.97
    elif cur.startswith("={"):
        value = -1.3
    elif TAG_CLOSE.search(cur):
        value = 1.8
    elif after_quote and cur == " (":
        value = 1.7
    elif after_quote and cur == " %":
        value = 2.7
    elif in_tag and after_quote and cur.lstrip().startswith("/>"):
        value = 3.0
    elif in_tag and after_quote and ATTR_NAME.match(cur):
        value = 1.0
    elif word in SQL_STRONG:
        value = SQL_STRONG[word]
    elif word in SQL_WEAK:
        value = 1.0
    elif word == "break":
        value = 1.0
    else:
        value = 0.0
    if "<" in cur and not cur.lstrip().startswith("<|"):
        in_tag = True
    if ">" in cur and in_tag and "=>" not in cur:
        in_tag = False
    return in_tag, value

"""Compound-completion detector for layers.1.mlp.down_proj:385.

The component fires on the token that finishes a multi-part compound term, the second
or later piece of a hyphenated or two-word modifier or noun phrase:
  - a hyphen suffix that completes an English compound: long-[term], real-[time],
    web-[based], high-[level], on-[line] (strongest for common
    compound heads such as -term, -time, -based, -level, -line, -order, -like, -free);
  - a closing word of a fixed two-word term: bottom [line], in [vitro], heavy [duty],
    twentieth [century], listed in COMPOUND_WORDS;
  - a possessive 's, and an ordinal ending (2[nd], 43[rd], 5[th]);
  - a second Chinese character inside a word (中大[型], 同[级]).
Everything else is predicted as 0. Values are scaled to the component's typical size
(values were shrunk after a fit showed the first version's were too large).

Main idea in plain terms: the component marks "we are in the middle of a compound term";
it is not a single-token detector, and most of its variance sits in the rare large values.
"""

COMPOUND_WORDS = {
    "scale", "duty", "based", "level", "sector", "side", "line", "time", "term", "order",
    "hand", "range", "century", "weight", "vitro", "vivo", "marrow", "panel", "package",
    "chain", "bound", "band", "driven", "step", "day", "life", "water", "mouth", "adult",
    "edge", "party", "state", "name", "point", "source", "Time", "Distance",
}
HYPHEN_WORDS = {
    "time", "term", "based", "level", "free", "like", "related", "dimensional", "order",
    "line", "type", "up", "year", "driven", "oriented", "scale", "duty", "side", "range",
    "end", "hand", "on", "chain", "bound", "part", "step",
}
READS = ()


def is_cjk(s):
    return len(s) == 1 and "一" <= s <= "鿿"


def step(carry, prefix, upstream):
    """Activation at the newest token, from the token and the one before it."""
    s = prefix.token_strings[-1]
    if s.startswith("-") and s[1:].isalpha() and len(s) > 2:
        return carry, 1.0 if s[1:] in HYPHEN_WORDS else 0.2
    if s.startswith(" ") and s[1:] in COMPOUND_WORDS:
        return carry, 0.4
    if s in ("'s", "’s"):
        return carry, 0.2
    if s in ("st", "nd", "rd", "th"):
        return carry, 0.3
    if is_cjk(s) and len(prefix.token_strings) > 1 and is_cjk(prefix.token_strings[-2]):
        return carry, 0.1
    return carry, 0.0

programs.sol:
"""Approximate a sparse spelling response, strongest on short er+a/o pieces.

Recognize rhotic syllables within a token or across its boundary with the
previous token. Short continuations and capitalized stems get larger responses;
accents usually weaken the cross-boundary response. A few unsplit words retain
it. Separate rules cover dew/frost characters and some non-Latin r syllables.
State resets at document boundaries, with a small negative start baseline.
These surface cues do not imply a common meaning for all the triggering words.
"""
from functools import lru_cache
import unicodedata

READS = ()


@lru_cache(maxsize=32768)
def plain(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    first = carry is None or carry[0] != doc
    previous, old_raw = ('', b'') if first else carry[1:]
    a, prev = plain(s), plain(previous)
    accent = a != s.lower()
    capital = any(c.isupper() for c in previous)
    value = -0.08 if first else 0.001

    # An exposed syllable is stronger than the same letters in a long word.
    if a.startswith('era'):
        value += 3.7 if len(a) == 3 else 1.4 if len(a) == 4 else 0.4
        value += 0.5 * capital - 1.0 * accent
    elif a.startswith('ero'):
        value += 1.4 if len(a) <= 4 else 0.5
    elif a.startswith('ere'):
        value += (0.25 if len(a) == 3 else 0.05) + 0.15 * accent
        value += 0.24 * capital
    elif a.startswith('eri'):
        value += 0.33 if len(a) == 3 else 0.06
    elif a in ('ara', 'ira', 'ora', 'ura'):
        value += 1.4 if a == 'ira' else 0.5 if a == 'ara' else 0.27
    elif len(a) == 4 and a.endswith('era') and a[0].isalpha():
        value += 0.5 if a[0] in 'aeiou' else 2.5

    # Complete the spelling when er and the following vowel are split.
    if prev.endswith('er'):
        if a.startswith('a'):
            n = len(a)
            small = accent or (s == 'A' and not previous.isupper())
            value += (0.4 if small else 4.0) if n == 1 else (
                (0.3 if accent else 1.4) if n == 2 else 0.25 if n == 3 else 0.03)
            if n == 1 and not accent:
                value += 2.0 * capital
            if n == 2 and prev.strip() == 'er':
                value -= 0.7
            if s == 'ă':
                value += 2.6  # Romanian breve-a ending.
        elif a.startswith('o'):
            value += (0.15 if accent else 1.4) if len(a) == 1 else (
                0.7 if len(a) == 2 else 0.4 if len(a) == 3 else 0.09)
            if len(a) <= 2 and prev.strip() == 'er':
                value -= 0.7
        elif a in ('et', 'en', 'em', 'eth', 'es'):
            value -= 0.3
        elif a == 'ella':
            value += 1.5
        elif a in ('er', 'i'):
            value += 0.2
    if a == 'um' and prev.endswith('r') and prev[-2:-1] in 'aeiou':
        value += 4.8 if prev.endswith('er') else 1.65
    if prev.endswith('e') and a.startswith(('ra', 'ro', 're')):
        value += 0.23 * (len(a) <= 3) + 0.26 * (prev != previous.lower())

    # Unsplit forms with the same prominent spelling.
    word = a.strip()
    if word == 'serum':
        value += 3.8
    if s.startswith(' ') and word in ('vera', 'vero', 'vere'):
        value += {'vera': 3.4, 'vero': 2.2, 'vere': 1.0}[word]
    if word == 'opera':
        value += 1.2 if 'O' in s else 0.4
    if s.strip() == 'ERA':
        value += 0.8

    # Dew/frost; the second UTF-8 byte also responds when split from the lead.
    if s in ('露', '霜'):
        value += 7.0 if s == '露' else 5.0
    elif s.startswith('露'):
        value += 2.8
    elif '露' in s:
        value += 0.2
    if raw == b'\x9c' and old_raw.endswith(b'\xe9'):
        value += 4.5
    if s in ('ラ', 'ロ', 'رو', 'ера'):
        value += 0.35
    return (doc, s, raw), value

"""Approximate a message-boundary and local-echo signal.

Recently repeated words or symbols usually give negative activations.
Word matching ignores case and edge punctuation; whitespace is not a key.
Immediate repeats are strongest, except for digits: adjacent
repeated digits belong to the same number and receive a smaller penalty.
Message ends respond more strongly after tool tags or text lacking final
punctuation. Other signals are document startup and a positive doubled
middle dot. Lexical variation is not modeled.
"""
import re
from functools import lru_cache

import regex

READS = ()

# Subtractions for a matching token at distance 1, 2, 3-4, or 5-8.
ECHO = {
    'other': (0.95, 0.22, 0.05, 0.025),
    'cjk': (1.20, 0.22, 0.08, 0.025),
    'digit': (0.08, 0.29, 0.06, 0.015),
    'zero': (-0.05, 0.05, 0.0, 0.0),
    'separator': (0.55, 0.02, 0.02, 0.02),
    'opening': (0.65, 0.02, 0.02, 0.02),
    'closing': (0.15, 0.0, -0.04, 0.0),
}


@lru_cache(maxsize=65536)
def describe(text):
    stripped = text.strip()
    word = re.sub(r'^[\W_]+|[\W_]+$', '', text).lower()
    key = word or stripped
    if not stripped or '\ufffd' in text:
        return '', 'other'
    if stripped.isdigit():
        return key, 'zero' if set(stripped) == {'0'} else 'digit'
    if all(ch in ',.;:!?，。；：！？、' for ch in stripped):
        return key, 'separator'
    if all(ch in ')]}）】》」』' for ch in stripped):
        return key, 'closing'
    if all(ch in '([{（【《「『' for ch in stripped):
        return key, 'opening'
    if regex.fullmatch(
        r'[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}ー]+',
        stripped,
    ):
        return key, 'cjk'
    return key, 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, position = [], 0
    else:
        history, position = carry[1:]
    text = prefix.token_strings[-1]
    previous = history[-1] if history else ''

    value = 0.01
    if text == '<|im_end|>':
        if previous == '</tool_call>':
            value = -1.80
        elif previous == '</tool_response>':
            value = -1.54
        else:
            tail = ''.join(history[-5:]).rstrip()
            if re.search(r"[.!?。！？][\s\"'”’）)\]}]*$", tail):
                value = -0.13
            elif tail[-1:].isalnum():
                value = -0.59
            else:
                value = -0.39
    elif text == '<|im_start|>':
        value = -0.08
    elif text == '··':
        value = 2.47
    elif not (text.startswith('<') and text.endswith('>')):
        key, kind = describe(text)
        if key:
            for lag, old in enumerate(reversed(history), 1):
                if key == describe(old)[0]:
                    if lag <= 2:
                        band = lag - 1
                    else:
                        band = 2 if lag <= 4 else 3
                    value -= ECHO[kind][band]

    if position == 0:
        value -= 0.43
    if position < 8:
        value -= 0.035
    return (doc, (history + [text])[-8:], position + 1), value

programs.haiku:
"""Layer-1 MLP down_proj component 388: mostly quiet, with a few kinds of token and place
that push it negative (and one run of dots that pushes it strongly positive).

Concepts, in order of how much they explain:
- start of a document: the first token of each document (and of each packed row) is
  negative, about -0.45;
- end-of-turn marker `<|im_end|>`: strongly negative (-1.7) when it closes a tool call or
  tool response, weakly negative (-0.3) after ordinary text;
- `+\\n` and a bare carriage return `\\r`: negative (-1.5);
- a line of indentation then a newline (4 or more spaces, then `\\n`): negative (-0.7);
- the escape codes written as text, `\\n` and `\\t` (-0.5), and `\\"` (-0.3);
- the repeated middle-dot token `··` (a dot-leader run): strongly positive (+2.5).
Everything else (words, digits, punctuation, most symbols) predicts 0.
"""
import re

READS = ()

DOC_START = -0.45
TOOL_CLOSE = {"</tool_call>", "</tool_response>"}
INDENT_LINE = re.compile(r" {4,}\n")
ESCAPE = {"\\n": -0.5, "\\t": -0.5, '\\"': -0.3}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    value = 0.0
    if cur == "··":
        value = 2.5
    elif cur == "<|im_end|>":
        value = -1.7 if prev in TOOL_CLOSE else -0.3
    elif cur in ("+\n", "\r"):
        value = -1.5
    elif INDENT_LINE.fullmatch(cur):
        value = -0.7
    elif cur in ESCAPE:
        value = ESCAPE[cur]
    if value == 0.0 and (len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]):
        value = DOC_START
    return None, value

programs.sol:
"""Sparse local syntax cues, mostly at the beginnings of code constructs.

Method receivers, include brackets and diff hunk headers give positive pulses;
dated clock suffixes and shell directory changes give negative ones. Other rules
cover literal delimiters, forum headings, document openers, repeated middle
dots, and the `df` prefix in nonbreaking-space-separated definition lists.
Outside these modes the prediction is zero. Retain only 240 characters of
history, resetting at document boundaries. This is a partial approximation;
weaker word-specific effects are left unmodelled.
"""
import re

READS = ()

# Code/heading markers when they are the very first token of a document.
DOCUMENT_OPENERS = {
    '#include': 0.984,
    'import': 1.015,
    'def': 2.321,
    'package': -0.525,
    '#': 0.636,
}


def predict(token, before):
    word = token.strip()
    tail = before.rstrip()
    initial = not before or before.endswith('<|endoftext|>')
    if initial and token in DOCUMENT_OPENERS:
        return DOCUMENT_OPENERS[token]
    if token == '··' and (initial or before.endswith('··')):
        return -1.575
    if token == 'df' and before.endswith('\xa0'):
        return 3.0
    if word in ('am', 'pm', 'AM', 'PM'):
        if re.search(r'\d\s*$', before):
            if word.isupper():
                return -0.146
            if re.search(r'\d:\d{2}\s*$', before):
                if not token[0].isspace():
                    return -0.55  # compact clocks, e.g. 9:30am
                if 'Joined:' in before[-90:]:
                    return -5.3
                if re.search(r'\b(?:19|20)\d{2}\b', before[-90:]):
                    return -3.23
                return -1.26
            if token[0].isspace() and re.search(r'\d\.\d{2}\s*$', before):
                return -0.6
            return -0.04
        if word == 'am' and re.search(r'\b[Ii]\s*$', before):
            return 0.086
    if word == 'cd':
        return -0.546
    if word in ('self', '(self'):
        if word == '(self' and re.search(r'\bdef\s+\w+\s*$', before):
            return 1.089
        if re.search(r'\bdef\s+\w+\(\s*$', before):
            return 1.089
        if re.search(r'&\s*mut\s*$', before):
            return 0.3 if '\n' in before[before.rfind('&'):] else 0.973
        if re.search(r'\bfn\s+\w+\s*\(\s*&\s*$', before):
            return 0.960
        if re.search(r'\(\s*mut\s*$', before):
            return 0.452
        return -0.036
    if tail.endswith('#include') and word.startswith('<'):
        return 1.254 if word == '<' else 0.262
    if word == '-' and tail.endswith('@@'):
        return 1.071
    if token == '#' and re.search(r'\br$', before):
        return 0.937  # Rust raw-string delimiter r#
    if token == 'EOF':
        return 1.169 if re.search(r'<<<?\s*[\'"]?$', before) else -0.200
    if token == 'dr' and before.endswith('\n'):
        return 0.731  # beginning of a directory's Unix mode string
    if word == 'Topics' and re.search(r'\bSimilar\s*$', before):
        return 1.2
    if word == 'Permissions' and tail.endswith('Posting'):
        return -0.25
    if token == 'param' and tail.endswith('@'):
        return -0.307
    if token.startswith('(`') and not tail.endswith('`'):
        return 0.347
    if word == '`' and re.search(r'(?<![=!<>])(?:=|:=)\s*$', before):
        return 0.293
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (doc, (before + token)[-240:]), value

"""Respond to the start of free-form strings, especially commands and SQL.

Quoted identifiers and prose quotes get little response. String concatenation,
formatting and output calls get more; executable strings get the most.
SQL-named variables and statement-preparation calls are also cues.
Only a short, document-local text tail is retained. Most other tokens get
zero, so this is a partial explanation rather than a model of every response.
"""
import re

READS = ()

OUTPUT = {'print', 'println', 'printf', 'fprintf', 'echo', 'log', 'info',
          'debug', 'warn', 'warning', 'writeline', 'alert', 'eprintln', 'write'}
FORMAT = {'sprintf', 'format', 'formatf', 'newf'}
APPEND = {'append', 'appendtext', 'concat'}
EXECUTE = {'system', 'exec', 'execute', 'eval', 'query', 'prepare'}
COMMAND_NAMES = {'command', 'cmd', 'script', 'new_str', 'old_str', 'program'}


def last_name(text):
    m = re.search(r'([A-Za-z_][A-Za-z_0-9]*)\s*$', text)
    return m.group(1).lower() if m else ''


def sql_name(name):
    return bool(re.search(r'sql|query|stmt|statement|commandtext', name))


def predict(token, before):
    before = before.replace('\\n', '\n').replace('\\t', '\t').replace('\\r', '\r')
    before = re.sub(r'\\+([\'"])', r'\1', before)
    bare = token.strip()
    name = last_name(token)
    previous = last_name(before)
    # Database statement preparation and use, not just its quoted text.
    if token == 'prepare' and before.rstrip().endswith(('->', '.')):
        return 4.5
    if token == '.CommandText':
        return 4.5
    if bare == '->' and sql_name(previous):
        return 2.5
    if token == bare and before.rstrip().endswith(('$', '->', '.')) and sql_name(bare.lower()):
        return 1.5
    if bare.lower() == 'sprintf' or bare == '(sprintf':
        return 4.5
    # The string-building operation can itself already be a useful cue.
    if token in {'.Sprintf', '.Format'}:
        return 3.0
    if token.startswith('.') and name in APPEND:
        return 4.0 if sql_name(previous) else 0.8
    if token in {'.Printf', ' fprintf'}:
        return 1.3
    if token == ' f' and before.rstrip().endswith('='):
        return 1.2
    if bare in {"'" * 3, '"' * 3} and before.rstrip().endswith('='):
        return 2.5
    if bare == '(f':
        return 2.0 if last_name(before) in OUTPUT else 0.4

    if bare.startswith('$"{') and len(bare) < 5:
        return 3.5
    if bare in {'<<', '<<"'} and re.search(r'\b(?:cout|cerr|clog)\b', before[-100:]):
        return 1.0 if bare == '<<' else 1.8

    # A quote at the end of opening punctuation, possibly with a string's
    # first punctuation character attached by the tokenizer.
