        if word == 'References' and line_start:
            return -3.34 if '#' in line else -2.12
        if text.endswith('Works Cited'):
            return -6.38
        if text.endswith('Bibliography'):
            return -3.26
        if word != 'References' or before.endswith('External'):
            return -3.61
    if re.search(r'\bExternal [Ll]inks\Z', text):
        return -4.19
    if re.search(r'\bFurther [Rr]eading\Z', text):
