    if token == ' also' and re.search(r'\b[Ss]ee\Z', before):
        return -1.38
    if token.isspace() and '\n' in token:
        if line.endswith('References'):
            return -2.48
        if BIBLIOGRAPHY.search(line):
            return -1.22
        if re.search(r'(?:External links|Further reading|See also)\Z', line):
            return -1.09

