                    if text == 'FS' or text.startswith('ST'):
                        value = -3.0
                if not previous[-1:].isupper():
                    value *= 0.2
    return None, float(value)

"""Recognize source/outward expressions, with sensitivity to token splitting.

'Out of' has a large negative value, as do the source prefixes German
'aus', Russian 'из' (also Latin 'iz'), Dutch 'uit', and Lithuanian 'iš'.
'From' and Chinese source words are weaker. Short pieces completing these spellings also
respond inside words; longer, unrelated whole words are not classified by
substring alone. Alternatives such as 'out to' have positive responses.
The carry remembers the last token and word ending, resetting per document.
"""
import re

READS = ()
VOWELS = set('aeiouаеёиоуыэюя')
DIRECTION_WORDS = {
    'out': -0.30, 'into': -0.20, 'back': -0.20,
    'over': -0.14, 'through': -0.14, 'between': -0.12,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, ending = '', ''
    else:
        _, previous, ending = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    low = s.lower()
    attached = bool(ending and token[:1].isalpha())
    left = ending.lower() if attached else ''
    value = DIRECTION_WORDS.get(low, 0.0)
    if low.lstrip('-') == 'of':
        value = 0.04

    if low.lstrip('._') == 'from':
        value = -1.0
        if s == 'FROM' or s.startswith(('.', '_')):
            value = -0.80
        elif token.startswith('\t'):
            value = -0.22
        elif token == 'from':
            if not previous:
                value = 2.3
            elif previous in ('\n', '\n\n'):
                value = 0.4
            elif previous == '\\n':
                value = 0.0

    prior = previous.strip()
    # A complete 'out' is stronger than a piece of a compound word.
    if prior.lower().lstrip('-') == 'out':
        if low.lstrip('-') == 'of':
            value = -14.0 if prior == 'Out' else -11.0
            if ending.lower() != 'out':
                value = -4.0
        elif low == 'to':
            value = 2.5
        elif low in ('from', 'for', 'in', 'into', 'there'):
            value = 2.1 if low == 'from' else 1.3
    elif low == 'outof':
        value = -9.5

    # These are short source-prefix fragments, not all words beginning
    # with the same letters (e.g. 'Australia' or 'известный').
    if low == 'aus':
        value = -3.8 if attached else -6.6
        if token == s and not attached:
            value = -8.5
    elif low == 'ausge':
        value = -7.7
    elif low == 'auss':
        value = -5.2 if s[0].isupper() else -3.6
    elif low == 'aust':
        value = -1.8
    elif low in ('из', 'iz'):
        cyrillic = low == 'из'
        if not attached:
            value = -6.6 if cyrillic else -4.5
            if cyrillic and (s[0].isupper() or token == s):
                value = -8.5
        elif left[-1] in VOWELS:
            value = -6.7 if cyrillic else -3.8
        else:
            value = -0.6
    elif low == 'uit':
        value = -7.6 if not attached else -0.6
        if left.endswith(('voor', 'daar', 'hier', 'er')):
            value = -8.5
    elif low in ('ис', 'исп') and (not attached or left[-1] in VOWELS):
        value = -2.1
    elif low == 'использ':
        value = -1.4

    # A short token can finish a source spelling begun in the last token.
    if attached and len(low) <= 4:
        if left.endswith('a') and low in ('us', 'uss', 'use', 'ust', 'ustr'):
            value = -5.0 if low == 'us' else -1.5
            if low == 'uss':
                value = -3.5
            if left == 'a':
                value = -7.5
        elif left == 'ä' and low.startswith('us'):
            value = -4.5
        elif left.endswith('au') and low.startswith('s'):
            value = -5.0
        elif ending == 'И' and low.startswith(('з', 'с')):
            value = -6.8
            if low == 'з' and ending.endswith('И'):
                value = -10.8
        elif left in ('u', 'vooru', 'eru', 'daaru', 'hieru') and low.startswith('it'):
            value = -3.7 if low.startswith('iter') else -2.0
            if low in ('it', 'itz'):
                value = -9.0
            if ending == 'U' and low == 'it':
                value = -11.0
        elif left == 'i' and low.startswith('š'):
            value = -10.0

    if prior.lower() == 'aus' and low in ('dem', 'ser', 'z'):
        value = -3.3
    elif prior.lower() == 'из' and low == 'г':
        value = -7.5
    # Russian 'one of' is partitive, not a source: weaken its из.
    if low == 'из' and ending.lower().startswith(('один', 'одн')):
        value = -2.0
    if low in ('从', '從', '来自', '來自'):
        value = -0.82

    match = re.search(r'[^\W\d_]+(?:-[^\W\d_]+)*\Z', ending + token, re.UNICODE)
    new_ending = match.group()[-24:] if match else ''
    return (doc, token, new_ending), value

"""Theta spellings with a decaying first-mention bonus.

Repeated mentions have a smaller bonus; Greek theta is also reduced after
trigonometric operators. The response extends briefly into Greek letters
following theta. Five- and six-hash runs have a separate positive response.
Other lexical effects are deliberately left at zero.
"""
import codecs
import unicodedata

READS = ()


def greek(char):
    return bool(char) and 'GREEK' in unicodedata.name(char, '')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', '', 0)
    _, pending, previous, before, mentions = carry
    data = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(data, 'replace', False)
    pending = data[used:]
    value = 0.0
    text = unicodedata.normalize('NFKC', text)
    lower = text.lower()
    is_theta = 'theta' in lower or any(c in text for c in 'θΘϑ')

    if 'theta' in lower:
        value = 4.2 + 3.3 / (1 + mentions) ** 1.5
        if text.startswith(' '):
            value += 1.3
        elif text.startswith('('):
            value += 1.0
        if 'Theta' in text:
            value += 0.6
    elif is_theta:
        value = 3.2 + 2.5 / (1 + mentions) ** 0.8
        if greek(previous[-1:]):
            value += 2.0
        if previous.strip().endswith(('sin', 'cos', 'tan', 'd')):
            value -= 0.8
        if 'Θ' in text:
            value += 4.0
    elif text and greek(text[0]) and previous.endswith(('θ', 'Θ')):
        base = unicodedata.normalize('NFD', text)[0]
        if len(text) > 1:
            value = 0.2
        elif base in 'εΕυΥ':
            value = 5.8
        elif base in 'αΑ':
            value = 4.4
        else:
            value = 0.8
    elif (text and greek(text[0]) and before.endswith(('θ', 'Θ'))
          and previous and greek(previous[0])):
        value = 1.2

    if text and set(text) == {'#'}:
        if len(text) in (5, 6):
            value = 3.3
            if '...' in previous:
                value = 7.2
            elif '#' in previous:
                value = 0.9
        elif len(text) == 2 and previous == ' ####':
            value = 10.0

    mentions += int(is_theta)
    if '<|endoftext|>' in text:
        return (doc, b'', '', '', 0), value
    if text:
        before, previous = previous, text
    return (doc, pending, previous, before, mentions), value

"""A vowel-less fragment followed by another piece of a word.

Look for a preceding Latin/Cyrillic/Greek letter fragment without a vowel.
Estimate its continuation response from case, fragment length, whether the
new piece starts with a vowel, and whether this word already had a vowel.
Short uppercase continuations receive the strongest response. Unusual
initial consonant clusters get a boost; familiar English onsets are damped. A separate
rule recognizes the initial Title: metadata label. Ordinary
text receives approximately zero. No tokenizer identities are stored.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()
VOWELS = frozenset('aeiouyаеёиоуыэюяαεηιουω')

# Common English word-initial consonant clusters, including digraphs.
COMMON_ONSETS = frozenset('''
    bl br ch cl cr dr dw fl fr gl gr kn ph pl pr qu rh sc sh sk sl
    sm sn sp st sw th tr tw wh wr sch scr shr sph spl spr squ str thr
'''.split())


@lru_cache(maxsize=30000)
def spelling(token):
    text = ''.join(c for c in unicodedata.normalize('NFD', token)
                   if not unicodedata.combining(c))
    match = re.search(r'([^\W\d_]+)$', text)
    tail = match[0] if match else ''
    western = bool(tail) and all(
        any(script in unicodedata.name(c, '')
            for script in ('LATIN', 'CYRILLIC', 'GREEK')) for c in tail)
    vowels = sum(c.lower() in VOWELS for c in tail)
    return text, tail, vowels, western


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text, tail, vowels, western = spelling(prefix.token_strings[-1])
    if carry is None or carry[0] != doc:
        previous = word = ''
        pieces = 0
        position = 0
    else:
        _, previous, word, pieces, position = carry
        position += 1
    _, prev_tail, prev_vowels, prev_western = spelling(previous)
    value = 0.0
    if prev_western and not prev_vowels:
        value = 0.008
        starts_vowel = bool(text) and text[0].lower() in VOWELS
        word_has_vowel = any(c.lower() in VOWELS for c in word)
        if text[:1].isupper():
            if not vowels:
                value = 0.034
            elif len(prev_tail) == 1:
                value = (0.64 if prev_tail.isupper() else 0.10)
                if starts_vowel:
                    value = 0.046
            else:
                value = 1.05 if len(tail) <= 2 else 0.14
        elif text.isalpha():
            if not starts_vowel:
                value = 0.031
                if vowels:
                    value = 0.07 if word_has_vowel else (
                        0.47 if len(tail) <= 4 else 0.105)
            elif len(word) <= 1:
                value = -0.020
            elif word_has_vowel:
                value = 0.018
            else:
                value = 0.14 if pieces == 1 else 0.57
        elif text.startswith(('-', '_')):
            value = 0.076
    if (prev_western and not prev_vowels and text.isalpha()
            and western and vowels and not word_has_vowel):
        onset = ''
        for char in text.lower():
            if char in VOWELS:
                break
            onset += char
        cluster = word.lower() + onset
        if len(cluster) >= 2:
            if cluster in COMMON_ONSETS:
                if onset:
                    value *= 0.5
            elif len(tail) <= 4:
                strength = 1.1 if word.isupper() else 0.7
                if previous.startswith(('/', '.', '_', '-')):
                    strength = 1.2
                value = max(value, strength)
    if position == 0 and text == 'Title':
        value = 0.814
    elif position == 1 and previous == 'Title' and text == ':':
        value = 4.246
    if text.isalpha() and word:
        word = (word + text)[-40:]
        pieces += 1
    else:
        word = tail[-40:]
        pieces = int(bool(tail))
    return (doc, prefix.token_strings[-1], word, pieces, position), float(value)

"""Approximate a formatting-boundary signal, not the content of sentences.

Blank lines after reasoning/tool tags and aligned file listings are negative.
Other paragraph breaks are much weaker. Small corrections cover document
beginnings and whitespace.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    age = carry[1] + 1 if carry is not None and carry[0] == doc else 0
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if age else ''
    value = 0.001

    if age == 0:
        if s == '<|im_start|>':
            value = -0.292
        elif s == '<|endoftext|>':
            value = 1.145
        elif s.isspace():
            value = 0.38 if '\n\n' in s else 0.01 if '\n' in s else 0.28
        elif s.isalpha() and not s.startswith(' '):
            value = -0.10
    elif '\n\n' in s:
        before = ''.join(prefix.token_strings[-min(age + 1, 31):-1])
        line = before.rsplit('\n', 1)[-1]
        if prev == '<think>':
            value = -0.49
        elif prev == '</think>':
            empty = before.endswith('<think>\n\n</think>')
            value = -0.30 if empty else -0.50
        elif prev == '<tool_response>':
            value = -0.35
        elif s == '\n\n' and prev.isspace() and '\n' not in prev:
            value = -0.75
        elif (re.fullmatch(r' *[\w./-]+(?: {2,}[\w./-]+)+ *', line)
              and ('.' in line or '/' in line)):
            value = -0.65 if s == '\n\n' else -0.43
        elif len(line) > 8 and not any(c.isalnum() for c in line):
            value = -0.30
        elif s.startswith(('.', ',', '。', '!', '?')):
            value = 0.035
        elif s.startswith(':'):
            value = -0.03
        else:
            value = -0.02 if s.startswith('\n') else 0.025
    elif s.isspace():
        value = 0.015 if '\n' in s else 0.006

    return (doc, age), value

