programs.sol:
"""Approximate a scholarly-reference and mathematical-typography signal.

Look for 'shown in'-type phrases, 'as before', numbered references, and
nonbreaking spaces after scholarly labels or within TeX prose. Standalone
accented Latin letters are treated as possible mathematical notation.
Most other tokens receive a small baseline. Document starts use a separate
offset, with exceptions for heading markers and escaped tabs. Context keeps
only 240 recent characters and whether this document has used '$'.
"""
import re
import unicodedata as ud
from functools import lru_cache

READS = ()
REPORT_VERBS = {
    'shown', 'defined', 'discussed', 'given', 'proposed', 'described',
    'depicted', 'illustrated', 'presented', 'reported', 'summarized',
    'listed', 'obtained', 'demonstrated', 'displayed', 'mentioned',
    'revealed', 'introduced', 'explained', 'considered', 'outlined',
    'studied', 'indicated', 'computed', 'noted', 'stated', 'suggested',
    'showed', 'used', 'known',
}
LABEL = re.compile(
    r'\b(?:eqs?|equations?|figs?|figures?|tables?|sections?|secs?|refs?|'
    r'references?|theorems?|lemmas?|corollar(?:y|ies)|propositions?|'
    r'conjectures?|definitions?|conditions?|appendi(?:x|ces)|propert(?:y|ies))\.?$',
    re.I)
MATH = re.compile(
    r'[$Α-ω∈∑∫≤≥∞]|\b(?:theorem|lemma|equation|proof|matrix|Hamiltonian)\b',
    re.I)

@lru_cache(maxsize=10000)
def accented(s):
    return (len(s.strip()) == 1 and 'LATIN' in ud.name(s.strip(), '')
            and any(c in ud.normalize('NFD', s) for c in '\u0302\u0303\u0304'))


def response(s, text, seen_tex):
    accent = accented(s)
    if not accent and s not in (
            ' in', ' before', ' above', ' below', ')', ']', '\xa0', '~'):
        return 0.003
    math = bool(MATH.search(text))
    if accent:
        if s.strip() in {'Â', 'Ã'}:  # Common UTF-8 mojibake prefixes.
            return 0.15
        if s.startswith(' '):
            return 0.10
        if s.isupper():
            return 3.5 if math else 0.3
        inside_word = bool(re.search(r'[A-Za-z]{2,}$', text))
        if math:
            return 1.57 if inside_word else 2.15
        return -0.08 if inside_word else 0.02
    previous = re.search(r'([A-Za-z]+)$', text)
    word = previous[1].lower() if previous else ''
    if s == ' in':
        if word == 'as':
            return 1.0 if math else 0.33
        if word in REPORT_VERBS:
            if math:
                return 0.87
            return 0.74 if re.search(r'\bas\s+\w+$', text, re.I) else 0.25
    if word == 'as' and s in (' before', ' above', ' below'):
        return 1.46 if s == ' before' else 0.37
    if s in ('\xa0', '~'):
        if LABEL.search(text):
            if s == '~':
                return 2.2
            if re.search(r'\bEqs?\.$', text, re.I):
                return 4.9
            if re.search(r'\b(?:Figs?|Secs?|Refs?)\.$', text, re.I):
                return 2.75
            general_label = re.search(
                r'\b(?:sections?|figures?|tables?|equations?|appendi(?:x|ces))$',
                text, re.I)
            return 0.72 if general_label else 3.24
        if s == '\xa0':
            if re.search(r'[A-Za-z]$', text):
                return 2.26 if '$' in text else (1.12 if seen_tex else 0.13)
            return 0.22 if text.endswith('.') else 0.04
    if s in (')', ']'):
        number = re.search(r'[\[(]\s*\d+(?:[.,-]\d+)*$', text)
        if number:
            left = text[:number.start()].rstrip()
            if s == ')' and (LABEL.search(left) or (math and re.search(
                    r'\b(?:from|in|by|to|of|and|or|using|between|'
                    r'formulas?|solutions?|problem)$',
                    left, re.I))):
                return 0.9
            return 0.22 if math else 0.07
    return 0.003


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    text, seen_tex = ('', False) if first else carry[1:]
    if first:
        if token.startswith('\\t'):
            value = -3.28
        else:
            value = 0.35 if token.startswith('#') else -0.38
    else:
        value = response(token, text, seen_tex)
    return (doc, (text + token)[-240:], seen_tex or '$' in token), value

programs.haiku:
"""Mathematical operation names, and the operand word right after one.

Layer 1's MLP down-projection, component 405, reads the MLP hidden state and writes a
small signal that is largest where the text names a mathematical operation or function
("sine", "logarithm", "factorial", "multiplication", "product", "sum", "OR", "union").
It is strongest on the word right after a function name ("sine of", "logarithm of",
"factorial of"), and near zero on most ordinary words. This program writes that as a
lookup on the current word and the word before it. Its strength is read off the
word lists below, not learned from the model.
"""
READS = ()

# Names of functions with a strong response (inverse/hyperbolic/trig/log, arithmetic ops).
STRONG = {" exponential", " cosine", " sine", " logarithm", " logarith", " factorial",
          " multiplication", " subtraction", " multiply", " multiplying", " quotient", " inverse",
          " arithmetic", " gcd", " lcm", " convolution", " modulo", " implication", " NAND",
          " squared", " minus", " exponent", " tangent", " subtract", " sums", " subtraction"}
# Other operation names: sums, products, differences, logical connectives, set operations.
MEDIUM = {" product", " sum", " difference", " division", " derivative", " union", " intersection",
          " absolute", " OR", " AND", " dot", " divide", " numerator", " inequality", " average",
          " integral", " mod", " multiplied", " operator", " complement", " squares", " combine",
          " differentiation", " derivatives", " log", " ln", " Sum", " Union", " sign", " square",
          " ratio"}
# Names that barely respond.
WEAK = {" sqrt", " sin", " cos", " tan", " maximum", " minimum", " add", " sub", " div", " root",
        " limit", " factor", " operation", " operations", " addition", " quadratic", " divided"}
# Frequent tokens with a small consistent offset.
SMALL = {"(": 0.15, "^": 0.2, " function": 0.3, "#": -0.25}
NEGATIVE_NUMBER_WORDS = {" integer": -0.55, " integers": -0.55, " digit": -0.5, " digits": -0.5,
                         "boxed": -1.0, "Hmm": -0.5}
OPERAND_WORDS = {" of", " by", "("}


def word_value(word):
    if word in STRONG:
        return 1.4
    if word in MEDIUM:
        return 0.6
    if word in WEAK:
        return 0.2
    return SMALL.get(word, NEGATIVE_NUMBER_WORDS.get(word, 0.0))


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if cur in OPERAND_WORDS and prev in STRONG:
        return carry, 2.4
    if cur in OPERAND_WORDS and (prev in MEDIUM or prev in WEAK):
        return carry, 0.9
    return carry, word_value(cur)

programs.sol:
"""A mixed reference-word and closing-delimiter detector.

Plural/inanimate pronouns, counterfactual modals and universal quantifiers
are positive. So are standalone closing brackets/quotes and single NBSPs
or tabs. Quoted strings, indexing and numbered-code indentation are
recognized from the current line. Other tokens get a small baseline, with
a document-start offset. Initial tabs and the initial Title: label are
negative exceptions.
"""
READS = ()

# Grammatical reference words, with stronger responses to plural/inanimate ones.
WORDS = {
    'they': 1.37, 'them': .93, 'their': .91, 'theirs': .61,
    'themselves': .31, 'it': .70, 'its': .26, 'itself': .05,
    'he': .24, 'she': .24, 'him': .19, 'his': .06,
    'we': .05, 'our': .05, 'you': .05, 'your': -.06,
    'my': -.05, 'me': -.03,
    'would': .77, 'could': .26, 'might': .18, 'will': .11,
    'must': .07, 'should': .04,
    'every': .54, 'everything': .89, 'everyone': .80,
    'everybody': .66, 'each': .11, 'both': .07, 'all': .04,
    'these': .16, 'those': .17, 'this': .04, 'that': .05,
    'ones': .20, 'someone': .15, 'anyone': .16,
    'nothing': .18, 'something': .07, 'anything': .12,
    'any': .07, 'another': -.07,
}
# Equivalent reference forms in other languages; require a word boundary.
FOREIGN = {
    'они': .77, 'их': .70, 'leur': .68, 'leurs': .66,
    'ihnen': .64, 'sich': .38,
}
CHINESE_PLURAL = {'他们', '她们', '它们', '他們', '她們', '它們'}


def quote_open(line, quote):
    """An apostrophe inside a word or a prime is not an opening quote."""
    at = line.rfind(quote)
    return at >= 0 and (at == 0 or not line[at - 1].isalnum())


def predict(s, previous, line, position):
    if position == 0:
        if s == '\t':
            return -4.76
        if s == ' ':
            return .75
        if s == ':':
            return .42
        if s == 'Title':
            return -.77
    # A particularly strong metadata-header response at the document boundary.
    if position == 1 and previous == 'Title' and s == ':':
        return -6.22
    word = s.strip().lower()
    if position == 0 and word in {'it', 'they'}:
        return .10
    if word in WORDS:
        if s == 'it':             # also an identifier/word fragment
            return .10
        if s == 'its':
            return .03
        if word == 'it' and s.strip() == 'It':
            return .82
        return WORDS[word]
    if s[:1].isspace() and word in FOREIGN:
        return FOREIGN[word]
    if s in CHINESE_PLURAL:
        return .65
    if s.endswith('的') and s[:-1] in CHINESE_PLURAL:
        return .47
    if s in {'して', 'って'}:      # Japanese conjunctive/quotative endings
        return 1.05
    if s in {'いて', 'て'}:
        return .60
    if s == '<tool_call>':
        return .375
    if s == '\xa0':
        return .99
    if s and not s.strip('\xa0'):
        return .24
    if s == '\t':
        if line.strip(' \t').isdigit():
            return .95
        return .53 if not line.strip() else .98
    if s.isspace():
        return .002
