    if w == '士':
        if tail.endswith(('教', '護', '学', '學', '人')):
            return 2.4
        if tail.endswith('書'):
            return 6.0
        if tail.endswith(('硕', '碩', '力', '瑪', '労', '浪')):
            return 4.5
        return 7.5
