        return 2.5 if tail.endswith(('水', '夯', '郷')) else 3.5
    if w == '斗':
        return 1.4
    if w == '仕':
        return 0.9
    if w in ('知识', '知識'):
        return 1.0
    if w == '人士':
        return 1.1
    if w in ('硕士', '碩士'):
        return 1.8
    if w in ('修士', '道士', '博士', '将士'):
        return 0.65
    if w == '尺' and not tail.endswith(('公', '英')):
        return 1.3
    if w == 'ツ' and tail.endswith('シャ'):
        return 0.95
    if w in ('ト', 'ート') and tail.endswith(('シ', 'シー')):
        return 0.8
    # Latin spelling fragments; token splitting affects the magnitude.
    if lower == 'dirt':
        return 2.5
    if w == 'lint' and tail.lower().endswith(('es', 'ts', 'js')):
        return 0.65
    if w == 'ST' and tail.endswith('S'):
        return -2.2
    if lower == 'shi' or (w == 'hi' and tail.endswith('s')):
        return 0.9
    if w == 'irt':
        if tail.lower().endswith('d'):
            return 3.4
        if tail.lower().endswith('th'):
            return 2.3
        if tail.lower().endswith(('sh', 'sk')):
            return 1.0
