            return 2.7
        if s == 'ิ' and tail.endswith(('ต', 'ศ')):
            return 1.3
    if w == 'ุด' and tail.endswith('ส'):
        return 1.85
    if w in ('่', '้') and tail.endswith('สิ'):
        return 1.65 if w == '่' else 0.65
    if w == 'ง' and tail.endswith('สิ่'):
        return 1.35
    if w == 'ว' and tail.endswith('สิ'):
        return 1.5
    if w == 'ส':
        return 0.6
