def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    history = b'' if first else carry[1]
    tail = history.decode('utf-8', errors='ignore')
    raw = prefix.token_bytes[-1]
    value = predict(prefix.token_strings[-1], tail, first, raw, history)
    return (doc, (history + raw)[-96:]), value

