        match = re.search(r'(\d+)$', text)
        if match:
            number = match[0]
            before = text[:-len(number)].replace('\\n', '\n')
            if before.endswith('.'):
                value = 0.2
            elif not before or not before.rsplit('\n', 1)[-1].strip(' \t>#*'):
                value = 0.0
            else:
                value = 1.0 - 0.18 * min(len(number) - 1, 4)
                if number == '0':
                    value += 0.35
                elif number == '1':
                    value += 0.1
                earlier = list(re.finditer(r'\d\.(.)', before, re.S))
                if earlier:
                    value += 0.2 if earlier[-1][1].isdigit() else -0.4
                else:
