                    value += 0.25
                if before.endswith(('_', '^', '–')) or fraction:
                    value = 0.2
                if before.endswith('__'):
                    value = 1.4
                if before.endswith(('v', 'V')):
                    value = 1.6
                if before.endswith('>'):
                    value = 1.8
                if before.rstrip().endswith('='):
