    if lower in {'up', 'down', 'out', 'above'}:
        return -3.4
    if lower in {'to', 'with', 'on', 'like'}:
        return -1.8
    if lower == 'or':
        return -2.8
    if lower in {'if', 'when', 'where', 'before'}:
