        closing = tail.count(')') - tail.count('(')
        balanced = line.count('(') <= line.count(')') + closing
        punctuation = not any(ch.isalnum() for ch in tail)
        if punctuation and (':' in tail or '{' in tail):
            if ':' in tail and '=' not in tail and balanced:
                value += -0.904
                value += -0.195 if '\\' in s else 0
                block = True
            elif '{' in tail and ':' not in tail:
                value += -0.617
                value += -0.236 if kw in ('if', 'elif') else 0
                block = True
        elif punctuation and closing > 0:
            if '(' not in line or balanced:
                value += -0.283 * min(2, tail.count(')'))
        elif s == ' then':
            value += -0.039
            value += -1.342 if any(ch in line for ch in '[$;') else 0
