            value += -0.312
        elif not line.strip() and not (previous and not previous.strip(' \t')):
            value += 0.366
            if previous == 'n' or previous.endswith('\\n'):
                value += 0.384
        elif previous.endswith(('"', "'", '`')):
            value += 0.306
    if s == '\n' and previous == 'user':
        value += 0.175
    word = s.strip().lower()
