"""A coarse metadata-separator response, plus a Thai-fragment response.

Capitalized field-label families set the negative strength of a following
colon. Topic lists and descriptions are strongest; quoted keys, namespaces,
and code-like lines are excluded. HTTP prefixes just after "Source:" also
get a negative value, while URL scheme delimiters get a small positive one.

Short Thai fragments get positive values, especially the short-u mark and
bo baimai (บ). The m/n/w and r/l letters are weaker after vowel/tone marks.
These are family-level approximations, not a table of every label or word.
A short text tail is carried forward and reset at document boundaries.
"""
import re
import unicodedata as ud

READS = ()

# Label families: their meanings, rather than tokenizer identities.
LABELS = (
    (set('subjects topics keywords tags authors contributors'.split()), -4.2),
    (set('description abstract synopsis'.split()), -3.0),
    (set('title summary'.split()), -1.5),
    (set('author publisher pages isbn doi references'.split()), -1.7),
    (set('from by source email mail address'.split()), -0.7),
    (set('views replies comments reviews answers'.split()), -1.3),
    (set('inputs args instructions directions question disclaimer'.split()), -0.85),
    (set('name date posted category topic subject text notes docs labels'.split()),
     -0.6),
    (set('q a answer input output note test tests'.split()), -0.25),
)
LIST_OR_DESCRIPTION = LABELS[0][0] | LABELS[1][0]
THAI_VOWELS = set('ะาำัิีึืุูเแโใไๅ')


def thai_mark(c):
    return '\u0e00' <= c <= '\u0e7f' and (
        ud.category(c).startswith('M') or c in THAI_VOWELS)


def value(tail, prev, token):
    s = token.lstrip()
    if s.lower() in {'http', 'https'} and re.search(r'\bSource\s*:\s*$', tail):
        return -2.0
    if s == '://' and prev.strip().lower() in {'http', 'https'}:
        return 0.14
    if s.startswith((':', '：')) and not s.startswith(('::', '://')):
        if any(c in s[1:] for c in '\"\'`'):
            return 0.0
        before = tail + token[:len(token) - len(s)]
        m = re.search(r'([^\W\d_]+)\s*$', before)
        line = before.rsplit('\n', 1)[-1]
        if not m or re.search(r'[{}=]|\t', line):
            return 0.0
        word = m.group(1)
        if not word[0].isupper() or (m.start() and before[m.start()-1] == '_'):
            return 0.0
        for labels, strength in LABELS:
            if word.lower() in labels:
                if word.isupper() and word.lower() in LIST_OR_DESCRIPTION:
                    strength *= 0.6
                return strength - 0.06
        return -0.06

    t = token.strip()
    if not t or len(t) > 2 or not all('\u0e00' <= c <= '\u0e7f' for c in t):
        return 0.0
    p = prev.rstrip()
    after_vowel = bool(p and thai_mark(p[-1]))
    if len(t) == 1:
        if t == 'ุ':
            out = 2.5
        elif t == 'บ':
            out = 4.0
        elif t in 'มนว':
            out = 0.8 if after_vowel else (2.0 if t == 'ม' else 1.5)
        elif t in 'กดจ':
            out = 1.05
        elif t in 'ทชห':
            out = 0.65
        elif t in 'รล':
            out = 0.15 if after_vowel else 0.55
        else:
            out = 0.07
        return out + (0.3 if p.endswith('บ') else 0.0)
    if not any(thai_mark(c) for c in t):
        if t.startswith('บ'):
            return 4.0
        if 'บ' in t:
            return 1.0
        if any(c in 'มนว' for c in t):
            return 0.25
    return 0.7 if t.startswith('ุ') else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, prev = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    prediction = value(tail, prev, token)
    return (doc, (tail + token)[-180:], token), prediction

