"""Field-label colon detector for layers.1.mlp.down_proj:413.

The component goes negative on the colon that closes a field label written at the start
of a line, as in forum posts, e-mail headers and form-like text: "Description:",
"Subject:", "Date:", "Posts:", "Joined:", "Message-ID:", "Tags:". Metadata field names
(the HEADER_KEYS below) get the strongest negative value; other short Title-Case labels
get a weak one. Colons inside sentences, clock times, and code stay at 0, as does every
other token."""

READS = ()

HEADER_KEYS = {
    "Subject", "From", "To", "Date", "Description", "Tags", "Posts", "Joined",
    "Message-ID", "Status", "Location", "Background", "Editor", "Content-Type",
    "Labels", "Posted", "Dates", "Instructions", "Inputs", "Source", "Title",
}
HEADER_VALUE = -1.0
LABEL_VALUE = -0.2
MAX_WORDS = 3
COLONS = (":", "：")


def is_colon(token):
    return token.rstrip() in COLONS or token.endswith(":\n") or token.endswith("：")


def is_title_case(line):
    """A short line of Title-Case words, e.g. 'Date' or 'Returns Address'."""
    words = line.split()
    if not 0 < len(words) <= MAX_WORDS:
        return False
    return all(w[0].isupper() or w[0].isdigit() or w[0] in "-(" for w in words)


def step(carry, prefix, upstream):
    if not is_colon(prefix.token_strings[-1]):
        return None, 0.0
    line = "".join(prefix.token_strings[:-1]).split("\n")[-1].strip()
    if not is_title_case(line):
        return None, 0.0
    if line in HEADER_KEYS or line.split()[0] in HEADER_KEYS or line.split()[-1] in HEADER_KEYS:
        return None, HEADER_VALUE
    return None, LABEL_VALUE

programs.sol:
"""Approximate a local phrase-completion signal.

Positive responses concentrate on requests ("call for", "appeal to"),
transfer/movement ("pass through/over"), and selected infinitive-taking verbs.
The rules give these lexical combinations fixed, empirical amplitudes, using
WordNet to recognize inflections. They require a complete previous-token word.
Separate rules cover doubled Greek lambda/sigma and runs of middle dots.
Unrecognized text stays near zero; other lexical effects are not modeled.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
PREPOSITIONS = {'to', 'for', 'from', 'on', 'upon', 'through', 'over',
                'along', 'down', 'up', 'out'}
ROOTS = set('call appeal appear fail failure as seem proceed cease hesitate '
            'look forward turn happen challenge aspire cater argue argument '
            'care hope pray wish evidence case reason petition pass take go '
            'follow cross watch hand view see hear read start period phase'.split())

@lru_cache(maxsize=8192)
def root(word):
    w = word.lower()
    if w in ROOTS:
        return w
    return next((b for b in wordnet.base_forms(w) if b in ROOTS), w)


def phrase(word, prep):
    w = root(word)
    if w == 'call':
        return {'for': 5.5 if word.lower() != 'called' else 3.6,
                'on': 2.7 if word.lower() == 'calls' else 5.0, 'upon': 5.0, 'from': 1.1,
                'to': .6, 'out': 2.0}.get(prep, -.06)
    if w == 'pass':
        return {'through': 3.1, 'over': 4.8, 'on': 3.0, 'from': 1.5,
                'to': 1.0, 'along': 2.5, 'down': 2.0, 'up': 1.8}.get(prep, -.06)
    if w == 'as':
        return (4.4 if word == 'As' else 1.4) if prep == 'for' else (
            1.2 if prep == 'to' else -.06)
    if prep == 'to':
        return {'appeal': 4.4, 'appear': 1.2, 'fail': 1.2, 'failure': .85,
                'seem': .34, 'proceed': 1.4, 'cease': 1.3, 'hesitate': .95,
                'look': .6, 'forward': .65, 'turn': .35, 'happen': .5,
                'challenge': .85, 'aspire': 1.0, 'cater': 1.5,
                'go': -.15}.get(w, -.06)
    if prep == 'for':
        return {'argue': 4.8, 'argument': 2.5, 'care': 2.8, 'hope': 2.2,
                'pray': 1.6, 'wish': 1.6, 'evidence': 1.6, 'case': 1.1,
                'reason': .6, 'petition': 1.2, 'appeal': 1.5,
                'look': .45}.get(w, -.06)
    if prep == 'from':
        return {'view': 1.8, 'see': 1.1, 'hear': 1.6, 'read': .8,
                'start': .6, 'period': 1.3, 'appeal': .4}.get(w, -.06)
    if prep == 'on':
        return {'take': .85, 'go': .35}.get(w, -.06)
    if prep == 'through':
        return {'go': .8, 'follow': 1.0}.get(w, -.06)
    if prep == 'over':
        return {'cross': 3.0, 'go': 2.3, 'watch': 3.5,
                'hand': 1.9, 'take': .5}.get(w, -.15)
    if prep == 'out' and w == 'phase':
        return 2.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is not None and carry[0] == doc:
        previous, word = carry[1:]
    else:
        previous, word = '', ''
    token = prefix.token_strings[-1]
    p = -.002
    prep = token.strip(' _-').lower()
    if prep in PREPOSITIONS:
        # Use complete words, not suffixes such as "As" inside "RNAs".
        p = phrase(word, prep) if word and previous.endswith(word) else -.06
    if token == '··':
        p = -3.0 if previous.endswith('·') else -1.5
    if token in {'λ', 'σ'} and previous:
        if token == previous[-1].lower():
            p = 4.0 if token == 'λ' else 2.4
    last_word = re.search(r'[A-Za-z]+$', word + token)
    word = last_word[0][-128:] if last_word else ''
    return (doc, token, word), p

"""Modern-year prefixes and an ox spelling family.

The main pulse is on the third digit of 201... or 202..., without looking
at the fourth digit. Explicit month names and nearby East Asian writing
strengthen it. The same pattern embedded in a longer number is weaker;
a leading 01 has a small negative response.

A second response recognizes ox/oxy/oxide spellings and their token splits,
oxygen-related words, and a few common ox names. These are approximate
rules, not an exhaustive account of this component's lexical responses.
