import calendar
import regex

READS = ()
MONTHS = {s.lower() for s in calendar.month_name if s}
MONTHS.update(s.lower() for s in calendar.month_abbr if s)
EAST_ASIAN = regex.compile(r'[\p{Han}\p{Hiragana}\p{Katakana}]')


def spelling_value(piece, previous_word):
    word = piece.strip()
    lower = word.lower()
    inside = piece == word
    previous = previous_word.lower()
    if lower in ('ox', 'oxy', 'oxid'):
        if inside:
            return 8.0 if lower == 'oxid' else 9.5
        return 6.0 if lower == 'ox' else (8.0 if lower == 'oxy' else 3.0)
    if inside and lower in ('x', 'xy') and previous.endswith('o'):
        if previous == 'pro':
            return 1.5  # proxy is much weaker than oxygen spellings
        if previous.endswith('hydro'):
            return 5.5 if lower == 'x' else 4.5
        return 9.0 if lower == 'x' else 6.0
    if inside and previous.endswith('ox'):
        if lower in ('id', 'ides'):
            return 8.8
        if lower == 'ide':
            return 5.2
        if lower in ('o', 'yl'):
            return 4.5
    # Cyrillic окс is the corresponding spelling of the ox sound.
    if inside and previous.endswith('ок') and lower.startswith('с'):
        return 8.5
    if lower.startswith('oxide'):
        return 5.0
    if lower.startswith(('dioxide', 'epoxy')):
        return 3.7
    if lower.startswith('oxygen') or lower == 'xygen':
        return 3.4
    if lower.startswith(('oxidat', 'oxidativ', 'antioxid')):
        return 2.3
    if lower.startswith(('toxic', 'toxin')) or lower == 'otoxic':
        return 1.3
    if word in ('Fox', 'Cox', 'Knox', 'FOX'):
        return 4.4
    if lower in ('oxford', 'xford'):
        return 2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        digits, word, tail, month, asian = '', '', '', False, False
    else:
        digits, word, tail, month, asian = carry[1:]
