    value = spelling_value(token, word)
    if token.isascii() and token.isdigit():
        if not digits:
            recent_words = regex.findall(r'\w+', tail)
            month = bool(recent_words and recent_words[-1].lower() in MONTHS)
            asian = bool(EAST_ASIAN.search(tail))
        if digits.endswith('20') and token in ('1', '2'):
            if digits == '20':
                value = 7.8 if token == '1' else 10.2
                if month:
                    value += 1.7 if token == '1' else 2.6
                if asian:
                    value += 1.7
            else:
                value = 3.0 if token == '1' else 4.0
        elif token == '1' and digits == '0':
