"""A surface-marker approximation, dominated by single asterisks.

Single stars usually give negative values, modulated by spacing, punctuation,
line position, and whether another separate star occurred within 32 tokens.
Double stars are weak; a document's first single star is positive instead.
Fullwidth stars follow the same rules. Other rules cover 此 ('this/here'),
its compounds and split UTF-8 encoding, pure middle-dot leaders, and the
colon in a document-initial Title: field. Other tokens return zero.
Carry keeps a short text tail and the last separate-star position, resetting
at every document boundary. This is a surface approximation, not a parser.
"""

READS = ()


def star_value(s, previous, tail, position, novel):
    n = s.count('*')
    if n != 1:
        return -0.2 if n == 2 else -0.8
    leading = s[:1].isspace()
    if position == 0:
        return 4.38 if s == ' *' else 1.5
    before, after = s.split('*')
    line_start = bool(tail) and not tail.rsplit('\n', 1)[-1].strip()
    lines = tail.rstrip(' \t\r').rsplit('\n', 2)
    last_line = lines[-2] if len(lines) > 1 else ''
    word = previous.strip()

    digit = previous[-1:].isdigit()
    value = (-1.1 - 0.3 * leading + 0.15 * digit
             + 0.35 * bool(before.strip()) + 0.55 * bool(after.strip()))
    if '/' in before:
        value += 1.4
    if '\n' in s:
        value += 0.55 + 0.25 * leading
    if any(c.isalpha() for c in s) and not line_start:
        value += 0.95
    if after.startswith('\\'):
        value += 0.6
    if word.isalpha():
        value += 0.2
    if previous.isspace():
        value -= 0.25
    if previous.endswith('\\'):
        value += 0.45
    if line_start:
        value += -1.2 + 0.8 * leading
        if '*' in last_line and '/*' not in last_line:
            value += 0.8
    if novel:
        value -= 0.55 - 0.1 * leading - 0.3 * digit
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail, last_star = 0, '', '', -1000
    else:
        _, position, previous, tail, last_star = carry
