            value = -6.7
        # At/from/to/regarding/since/by this: prepositional compounds.
        elif core.endswith('此') and core[:1] in '在从從至对對自以':
            value = -4.6
        elif core == '因此':
            value = -0.5
        else:
            value = -1.8
