"""A document-onset pulse, estimated from the initial token's surface type.

Emit zero after the first token. At onset, use whitespace, script, punctuation,
numbers, English function-word classes and recognizable source-file markers.
For other Latin words/fragments, use case, leading space and English frequency.
These are approximations: individual tokens retain unexplained differences.
"""
import regex
from wordfreq import zipf_frequency

READS = ()

PREPOSITIONS = set(
    'of in on at to for from with by into onto upon over under between '
    'through during without within about against until before after as per via'
    .split()
)
ARTICLES = set('a an the'.split())
PRONOUNS = set(
    'i me my mine we us our ours you your yours he him his she her hers it its '
    'they them their theirs this that these those who whom whose which what'
    .split()
)
CONJUNCTIONS = set(
    'and or but nor so if because while although though whether'.split()
)
BE = set('am is are was were be been being'.split())
AUXILIARIES = set(
    'do does did have has had can could will would shall should may might must'
    .split()
)
EAST_ASIAN = regex.compile(
    r'\p{Script=Han}|\p{Script=Hiragana}|'
    r'\p{Script=Katakana}|\p{Script=Hangul}'
)


def onset(s):
    word = s.strip()
    lower = word.lower()
    # Source-file openings, escaped characters, and heading/comment markers.
    if word.startswith('#!'):
        return 12.93
    if word.startswith('\\'):
        return 11.13
    if word and set(word) == {'#'}:
        return 0.17
    if word == '//' and '\n' not in s:
        return 0.18
    if s == 'import':
        return 15.57
    if s == 'package':
        return 0.38
    if s.startswith('<|') or s.startswith('<tool'):
        return 0.21
    if not word:
        if '\t' in s:
            return 8.02
        if '\n' in s or '\r' in s:
            return 2.12
        return 0.13 if s == ' ' else 5.77
    if word.isascii() and word.isdecimal():
        if word == '0':
            return 7.23
        return 2.58 if word == '1' else 5.30
    if not any(c.isalnum() for c in word):
        if '\ufffd' in word:
            return -1.01  # An incomplete byte-level Unicode character.
        if not word.isascii():
            return 0.75
        if '\n' in s or '\r' in s:
            return 4.02
        return 2.47 if word in '()[]{}' else 4.51
    if EAST_ASIAN.search(word):
        return -0.11
    if not regex.search(r'\p{Script=Latin}', word):
        return -0.42
    if lower in ARTICLES:
        return 4.04
    if lower in PREPOSITIONS:
        return 8.11
    if lower in PRONOUNS:
        return 4.23
    if lower in CONJUNCTIONS:
        return 5.72
    if lower in BE:
        return 6.30
    if lower in AUXILIARIES:
        return 4.74
    if not word.isalpha():
        return 6.55

    # Rare bare fragments tend higher; rare space-led fragments tend lower.
    space = s.startswith(' ')
    rarity = max(0.0, 3.0 - zipf_frequency(word, 'en'))
    capitals = len(word) > 1 and word.isupper()
    short_title = len(word) <= 3 and not word.isupper() and word.istitle()
    return (6.40 - 0.91 * space + 0.61 * rarity * (1 - 2 * space)
            - 2.02 * capitals - 1.44 * short_title)


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, onset(prefix.token_strings[-1]) if first else 0.0

programs.haiku:
"""Document-start detector: fires on the first token of each document, with a strength set
by what that token is. Latin-script word pieces and code tokens fire strongly; non-Latin scripts
and special tokens barely fire. Everywhere else it is silent (0)."""
import unicodedata

READS = ()

NON_LATIN_MIN = 0x0250  # code points from here up are non-Latin scripts (Greek, Cyrillic, CJK, ...)


def is_latin_text(s):
    return all(ord(ch) < NON_LATIN_MIN for ch in s)


def strength(s):
    if s.startswith("<|") or not s.strip() and s == "":
        return 0.0
    if not is_latin_text(s):
        return 0.5
    body = s.lstrip(" ")
    if body[:1].isalpha() and not s.startswith(" "):
        return 7.0 if body[0].islower() else 6.0
    if body[:1].isalpha():
        return 4.5
    return 5.0


def step(carry, prefix, upstream):
    t = prefix.position
    starts_doc = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not starts_doc:
        return None, 0.0
    return None, float(strength(prefix.token_strings[t]))

programs.sol:
"""A strong opening-token signal and a weaker negative waiting signal.

At each row/document start, estimate strength from the token's ordinary
text category: numeral, indentation, letter, word, or punctuation. Keep
this response through repetitions of that opening token, then fall quiet
except for waiting and hesitation words. These are category averages,
not an exact model of the substantial variation between opening words.
"""
import unicodedata

READS = ()


# The ten ordinary decimal digits, in numerical order.
DIGIT_RESPONSE = (7.02, 12.02, 11.01, 8.05, 10.23,
                  8.84, 11.04, 10.21, 9.36, 3.49)
DEPENDENCY_DECLARATIONS = {"package", "import", "using"}
FUNCTION_WORDS = set("""
i me my you your he him his she her it its we us our they them their
this that these those there is are was were be been being do does did
have has had will would can could should may might must and but or if
for from to of in on at by as with without not no so than
""".split())


def opening_response(token):
    word = token.strip()
    if token in '0123456789' and len(token) == 1:
        return DIGIT_RESPONSE[int(token)]
    if token.startswith('<|'):
        return 2.3
    if token.isspace():
        if '\n' in token or '\r' in token:
            return 0.0
        if '\t' in token:
            return 8.1 if token == '\t' else 4.0
        if token == ' ':
            return 3.08
        return 5.3 if token.isascii() else 0.7
    if word.startswith('/*'):
        return 3.4
    if '\n' in token or '\r' in token:
        return 0.0
    if word.startswith('\\'):
        return 4.5
    if token.startswith('#') and len(token) > 1:
        return 5.3 if token[1] != '!' else 2.0
    if not token.startswith(' ') and word in DEPENDENCY_DECLARATIONS:
        return 5.2
    if word.lower() in {'wait', 'waits', 'waiting', 'waited'}:
        return -1.4
    if word.lower() == 'well':
        return -2.0
    # One-letter words are not just initials or letter fragments.
    if token == 'I':
        return 2.9
    if token in {'a', 'A'}:
        return 5.4
    # Abbreviated titles commonly introduce names.
    if token in {'Mr', 'Mrs', 'Ms', 'Dr', 'Prof', 'St'}:
        return 6.3
    if len(word) == 1 and word.isalpha():
        if token.startswith(' '):
            return 2.6
        if word.isupper():
            return 4.6
        return 2.9 if word.islower() else 1.5
    if word.isalpha():
        if not word.isascii():
            return 1.7
        if token.startswith(' '):
            if word.isupper():
                return 2.4
            if word.lower() in FUNCTION_WORDS:
                return -0.25
            return 0.8 if word.istitle() else 0.35
        if word == 'The':
            return 2.67
        if word.isupper():
            return 2.8
        if word.lower() in FUNCTION_WORDS:
            return 0.6
        if word in {'How', 'What', 'Why', 'Where', 'When', 'Who'}:
            return 3.0
        if len(word) == 2:
            return 1.8 if word.istitle() else 0.8
        return 0.9
    if len(word) == 1:
        if token.startswith(' '):
            return 2.0 if word in '-+*/=$' else 0.1
        if unicodedata.category(word) in {'Ps', 'Pe'}:
            return 2.7
        if word in ':;：；':
            return -0.8
        if word in '/*^<>':
            return 2.8
        return 0.1
    return 1.5


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, prefix.token_ids[-1], True)
    document, first, opening_run = carry
    # Compare identities, not decoded strings: byte fragments may look alike.
    opening_run = opening_run and prefix.token_ids[-1] == first
    if opening_run:
        value = opening_response(token)
    else:
        word = token.strip().lower()
        if word in {'wait', 'waits', 'waiting', 'waited'}:
            value = -1.15 if word in {'wait', 'waits'} else -0.6
        elif word in {'hmm', 'hmmm'}:
            value = -0.47
        elif token.strip() == 'Ah':
            value = -0.15 if token.startswith(' ') else -0.23
        elif word == 'oops':
            value = -0.23
        else:
            value = 0.0
    return (document, first, opening_run), value

programs.haiku:
"""layers.1.mlp.down_proj:420 -- a "document-start" feature.

What it does: this component is almost silent inside a document. Its large
activations happen on the FIRST token of a document (the position where the
model's attention has nothing before it but the token itself). There, its
activation is set by what kind of token that first token is:

  * a digit (0-9)                                  -> large, about 7-12
    (1, 2, 6 are the largest; 9 is small)
  * a single letter, or a code marker such as
    "#include", "package", "import"                 -> about 5
  * indentation (spaces or a tab, no newline)       -> about 5
  * a capitalised word that is not a function word
    (a name, an acronym, a rare word)              -> about 3
  * a capitalised function word ("The", "This")     -> about 1
  * a lowercase common word, punctuation, newline   -> about 0

If a document opens with a digit and then repeats that same token
("0000...", "666..."), the repeats carry the same value. Mid-document,
hesitation words ("Wait", "wait", "Hmm") push it negative, about -1.

Everything else is 0. Predictions are the activation in the component's own
units.
"""

DIGIT_VALUE = {"0": 7.0, "1": 12.0, "2": 11.0, "3": 8.0, "4": 10.2,
               "5": 8.8, "6": 11.0, "7": 10.2, "8": 9.3, "9": 3.5}
CODE_WORDS = {"package", "import", "using", "def", "const", "int", "include",
              "#include", "#ifndef", "public", "class", "var", "let"}
FUNCTION_WORDS = {"the", "a", "an", "and", "or", "of", "to", "in", "on", "at", "by",
                  "for", "with", "from", "as", "is", "are", "was", "were", "be", "it",
                  "this", "that", "these", "those", "he", "she", "they", "we", "you",
                  "i", "not", "but", "if", "so", "there", "here", "what", "which",
                  "who", "how", "when", "where"}
HESITATION = {"wait", "waiting", "hmm", "ait"}

READS = ()


def start_value(s):
    """Activation of a document's first token `s`, from what kind of token it is."""
    if s in DIGIT_VALUE:
        return DIGIT_VALUE[s]
    if s.strip() == "":
        return 0.0 if "\n" in s else 5.0
    if s.startswith("<|"):
        return 2.0
    if s.startswith("#") and len(s) >= 2:
        return 5.0
    if s.lower() in CODE_WORDS:
        return 5.0
    if len(s) == 1 and s.isalpha():
        return 5.0
    if s[0] == " ":
        return 2.0 if s[1:2].isupper() else 0.0
    if s.lower() in FUNCTION_WORDS:
        return 1.0 if s[0].isupper() else 0.0
    if s[0].isupper():
        return 3.0
    if s[0].islower():
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    # carry: (the document's first token, whether every token since then repeats it)
    tok = prefix.token_strings[-1]
    starts_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_doc:
        first, repeating = tok, True
    else:
        first, repeating = carry
        repeating = repeating and tok == first
    if starts_doc or repeating:
        value = start_value(first)
    elif tok.strip().lower() in HESITATION:
        value = -1.0
    else:
        value = 0.0
    return (first, repeating), value

programs.sol:
"""Approximate the component's onset, numeric, and auxiliary-word responses.

Most positions get nearly zero. Opening tokens (including a repeated opening
run) get a shape-based estimate, mildly adjusted by English word frequency.
Inside a document, leading 19/20 pairs and numeric periods are negative;
line-start numbers and digits after another decimal point are exceptions.
Opening 12 and Chinese numeral 19 have additional negative rules.
Pronoun + can/could, some foreign ability forms, and going/about + to get
positive values. Double backslashes near recognized TeX commands are positive;
otherwise they are negative. A TeX backslash followed by cr is also positive.
These local rules approximate, rather than recover, the full contextual signal.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=20000)
def onset(s):
    w = s.strip()
    if not w:
        if s == '\r':
            return -3.54
        if s == '\n':
            return 3.2
        if s == ' ':
            return 0.64
        if s == '\t' or s == '  ':
            return 1.15
        return 1.8
    if w.startswith('<|'):
        return 1.65
    if w.isdigit():
        if w in {'0', '3'}:
            return 2.52
        if w == '1':
            return 0.80
        return 1.90 if w == '2' else 1.40
    if w.isascii() and w.isalpha():
        frequency = zipf_frequency(w.lower(), 'en')
        return (3.4 - 1.0 * s.startswith(' ')
                - 0.15 * max(frequency - 5, 0))
    return 2.5

SUBJECTS = {'i', 'you', 'he', 'she', 'it', 'we', 'they'}
# Inflected forms and stems of 'can' in several corpus languages.
ABILITY = re.compile(
    r'^(kan|kann|können|может|могут|могу|можно|можете|'
    r'peux|peut|peuvent|pouvez|pued.*|poder|pode[mn]?|pot|può|thể)$'
)
MATH = re.compile(
    r'\\(?:frac|begin|left|right|math|text|sum|int|alpha|beta|'
    r'gamma|sigma|hfill|infty|rangle|langle|nonumber|pmatrix)'
)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, '', True, True)
    # Retain the previous token, a text tail, and the current digit run.
    # 'origin' precedes that run; 'opening' tracks repeated opening tokens.
    _, prev, text, count, origin, line_start, opening = carry
    start = not text
    value = -0.005
    opening = start or (opening and s == prev)
    if opening:
        value = onset(s)
    elif text == '1' and s == '2':
        value = -8.6
    elif s == '九' and text.endswith('一'):
        value = -2.8
    elif s == '.' and prev.isascii() and prev.isdigit():
        if line_start:
            value = 0.08
        elif origin.endswith('.'):
            value = -0.08
        else:
            value = -0.5 if count > 1 else -0.9
            if count == 1 and prev in {'0', '1'}:
                value = -1.45
    elif (prev, s) in {('1', '9'), ('2', '0')}:
        if count == 1:
            value = -1.5 if s == '9' else -1.1
            if origin.strip() in {'=', '-', '+', '*'} and origin.startswith(' '):
                value = 0.0
            elif origin in {'-', '/', '.', ':', '('}:
                value = -0.65
        else:
            value = 0.05 if s == '9' else 0.34
    elif s == '8' and prev == '1' and count == 1:
        value = -0.18
    elif s == '.' and (
        len(prev.strip()) == 1 and prev.strip().isupper()
        or prev.strip() in {'Mr', 'Mrs', 'Dr', 'Prof', 'St', 'No', 'vs', 'v'}
    ):
        value = -0.35
    elif s.lower() in {' can', ' could'}:
        value = (0.62 if s.lower() == ' can' else 0.45)
        if prev.strip().lower() not in SUBJECTS:
            value = 0.05
    elif s.startswith(' ') and ABILITY.fullmatch(s.strip()):
        value = 0.55
    elif s == ' to' and prev in {' going', ' about'}:
        value = 1.0
    elif '\\\\' in s:
        value = 1.5 if MATH.search(text) else -0.75
    elif s == 'cr' and prev.rstrip().endswith('\\'):
        value = 2.8
    if s.isascii() and s.isdigit():
        if not (prev.isascii() and prev.isdigit()):
            count, origin = 0, prev
            line_start = not text.split('\n')[-1].strip()
        count += len(s)
    else:
        count = 0
    carry = (doc, s, (text + s)[-200:], count, origin, line_start, opening)
    return carry, float(value)

"""Approximate a short-spelling detector: S--L positive, S--X/digits negative.

The strongest positive patterns are short sal/sil/sale-like pieces, even
across token boundaries (tens + ile). Long completed words are much weaker.
X or digits extending an S-ending abbreviation usually have the opposite
sign. Cosine notation is an exception to the S--X rule. A secondary rule
recognizes Greek sibilant + iota. Unrelated lexical responses are omitted.
"""
import re
import unicodedata

READS = ()
FUNCTION_WORDS = {'is', 'as', 'was', 'has', 'his', 'this', 'its', 'us', 'does'}


def unaccent(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if not unicodedata.combining(c))


def predict(s, previous):
    raw = s.strip()
    t = unaccent(raw.lower())
    p = unaccent(previous.lower())
    word = previous.strip()
    joined = not s[:1].isspace() and not previous[-1:].isspace()
    value = 0.0

    # A short S-vowel-L piece within the newest token.
    m = re.search(r's([aiı]i?)l', t)
    if m and len(t) <= 6 and (m.start() == 0 or len(t) <= 4
                                 or t.startswith('re')):
        rest = t[m.end():]
        if not rest or rest == 'l':
            value = 2.9 if m[1] != 'i' or not raw[:1].isupper() else 1.9
        elif rest == 'e':
            value = 4.0 if raw[:1].isupper() else 3.4
        elif rest in ('s', 'es'):
            value = 2.1
        elif len(rest) <= 2 and rest.startswith('a'):
            value = 1.3
        else:
            value = 0.1
        if m.start() and t[:m.start()].isalpha() and not t.startswith('re'):
            value *= 0.35 if m[1] == 'a' else 0.55
        elif joined and previous[-1:].isalpha():
            value *= 1.4

    # The same letter pattern split between two tokens.
    if joined:
        tail = re.search(r'([szx])([aeiouyı]{0,2})$', p)
        lead = re.match(r'([aeiouyı]{0,2})l', t)
        if tail and lead:
            between = tail[2] + lead[1]
            rest = t[lead.end():]
            n = len(rest)
            if between in ('a', 'i', 'ı', 'ai'):
                if n == 0:
                    value = 5.0
                elif n == 1 and rest in 'aeioulsy':
                    value = 4.4 if between == 'a' else 3.8
                elif n == 2:
                    value = 4.0 if between == 'a' else 2.5
                else:
                    value = 0.6
                if between == 'i' and n and len(word) == 2:
                    value *= 0.65
            elif between:
                value = 0.7 if between[0] in 'ey' else 0.3
            else:
                value = 0.25
            if tail[1] != 's':
                value *= 0.25

    # S--X, especially JSX/TSX and capital-letter abbreviations.
    if joined and p.endswith('s') and t.startswith('x'):
        if re.fullmatch(r'(?:arc|a)?cos', word.lower()):
            value = 0.0
        elif len(t) > 1:
            value = -6.0 if raw.isupper() else -3.0
        elif p.endswith(('js', 'ts')) or word.isupper() and len(word) == 2:
            value = -8.0
        else:
            value = -4.0 if len(word) <= 4 else -1.0
    elif t in ('sx', 'jsx', 'tsx'):
        value = -3.2
    elif raw == 'X' and word.isupper() and len(word) == 2 and p.rstrip().endswith('s'):
        value = -5.5

    # Numerical continuations: stronger for short capital abbreviations.
    if len(t) == 1 and t.isascii() and t.isdigit() and not s[:1].isspace():
        letters = re.search(r'([A-Za-z]+)$', word)
        w = letters[1] if letters else ''
        if w and w not in FUNCTION_WORDS:
            digit = int(t)
            if w.lower().endswith('s') and len(w) <= 3 and digit:
                value = -2.5 if digit in (3, 4) else -0.6 if digit < 3 else -1.4
                if len(w) == 2 and w.isupper() and set(w) != {'S'}:
                    if digit in (3, 4):
                        value = -4.2 if digit == 3 else -6.1
                    else:
                        value = -1.5 if digit < 3 else -2.9
                elif len(w) == 3:
                    value *= 0.45
                if previous.endswith(' '):
                    value *= 0.5
            elif w.lower().endswith('x'):
                if digit == 8:
                    value = -1.0
                elif digit in (5, 6, 7):
                    value = -0.55
                else:
                    value = -0.2 if digit in (3, 4, 9) else 0.0
    if re.fullmatch(r'\\+x', s):
        value = -0.62 if len(s) == 2 else -1.0
    if t == 'ι' and p in ('σ', 'ς', 'ξ', 'ψ'):
        value = -4.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = predict(s, previous)
    code = previous.strip()
    keep_space = code.isupper() and len(code) <= 3 or code in ('s', 'x')
    remembered = previous.rstrip() + s if s == ' ' and keep_space else s
    return (doc, remembered), float(value)

"""A lexical response to getting things and to executable return statements.

Get's inflections and split g+ot spellings are negative; getter declarations
and member access are not. Main-verb 'do' after an infinitive or modal is negative;
auxiliary 'do' is not. Return is stronger as code than as an English verb.
Two format effects are kept separate: an opening Title: header, and repeated
middle dots used as a divider. String replacement and git command/directory
tokens also have fixed negative responses. At document starts a small bias depends on
token shape; other tokens are approximated by zero.
"""
import re

READS = ()
GET_FORMS = {'get': -0.85, 'gets': -0.85, 'got': -0.76,
             'getting': -0.98, 'gotten': -0.96}
DECLARATIONS = {'def', 'function', 'fn', 'func', 'int', 'long', 'void',
                'double', 'float', 'string', 'bool', 'const', 'import'}
MODAL = re.compile(
    r"(?:\b(?:to|can|could|will|would|shall|should|must|may|might|not)"
    r"|n['’]t)(?:\s+(?:still|just|even|also|really|never))*\s*$", re.I)
QUESTION = re.compile(
    r'\b(?:do|did|can|could|would|will|should)\s+(?:i|you|we|they|he|she)\s*$',
    re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, previous, text = 0, '', ''
    else:
        _, n, previous, text = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().lower()
    value = 0.0

    if n == 1 and previous == 'Title' and token == ':':
        value = 7.7
    elif token == '··' and (n == 0 or previous.endswith('·')):
        value = -1.93
    elif token.lower() in {'ot', 'ote'} and previous.lower().endswith('g'):
        value = -1.1 if word == 'ot' else -0.6
    elif word in GET_FORMS:
        value = GET_FORMS[word]
        if word == 'get':
            if prev in DECLARATIONS or prev.endswith(('=', '{', '>', '[]')):
                value = 0.12
            elif not token[0].isspace() and previous.endswith(('.', '->', '::')):
                value = 0.15
            elif not token[0].isspace() and not previous.endswith('\n'):
                value = -0.3
            elif token.strip() == 'Get':
                value = -0.6
    elif word == 'do':
        value = -0.7 if MODAL.search(text) or QUESTION.search(text) else 0.02
    elif word == 'doing':
        value = -0.36
    elif word == 'done':
        value = -0.19
    elif word == 'return':
        if token.startswith('\t'):
            value = -0.8
        elif previous.isspace() or prev.endswith(')') or prev == 'else':
            value = -0.78
            if text.rstrip().endswith('{'):
                value = -0.33
        elif not token[0].isspace():
            value = -0.37
        else:
            value = -0.12
    elif token == '_replace':  # string replacement operation
        value = -0.65
    elif word in {'git', '.git'}:  # version-control command/directory
        value = -0.59 if word == '.git' else -0.36

    if n == 0 and value == 0.0:
        # The left-edge bias differs for articles, numbers, and other tokens.
        if token.strip() == 'a':
            value = 0.37
        elif word in {'a', 'an', 'the'}:
            value = -0.52
        elif word.isascii() and word.isdigit():
            value = -0.3
        else:
            value = -0.12

    return (doc, n + 1, token, (text + token)[-160:]), value

programs.haiku:
"""Layer 1 MLP down-projection, component 423: a negative "get" / "return" detector.

What it does, in plain terms:
- Mid-sentence forms of the verb "get" (" get", " gets", " got", " gotten", " getting")
  push this component strongly negative (about -0.8 to -1.0). This is the main job.
- "return" used as a code statement (after indentation or a closing parenthesis) is
  also strongly negative (about -0.6 to -0.9). "return" in prose ("to return") stays near 0.
- The infinitive "do" ("to do", "can do") is moderately negative (about -0.65), while
  "I do", "how do" and "did" are near 0. "doing" and "done" are weakly negative.
- Sentence-initial "Get" is milder (-0.45). Bare "get" with no leading space, as in an
  identifier, is weak (-0.15). A "get" that names a getter method in a declaration
  ("public int get...", "public function get...") is left at 0.
- A few other action verbs (take, use, remove, load, ...) are weakly negative (-0.15).
- Two rare oddities are included because they dominate the variance when they occur:
  a run of middle-dot leader tokens "··" (-1.9), and the colon of a "Title:" that opens
  a document right after <|endoftext|> (+7.7).

Everything else is 0. The program only looks at the current token and the one or two
tokens before it.
"""

READS = ()

GET_MID = {" get", " gets", " getting", " got", " gotten"}
GET_START = {" Get", "Get", " Gets", " Getting", " Got"}
ACTION_VERBS = {" take", " use", " using", " remove", " load", " obtain", " save", " send"}
DO_AFTER = {" to", " can"}
DECL_WORDS = {"public", "private", "protected", "override", "static", "function", "def", "int", "long", "double", "String", "void", "bool", "boolean", "Object", "string", "float", "virtual", "async"}


def _is_indent(s):
    return s.strip() == "" and len(s) > 0


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""

    # A "Title:" header opening a document: the colon right after "Title" after <|endoftext|>.
    if cur == ":" and prev == "Title" and prev2 == "<|endoftext|>":
        return carry, 7.7

    if cur == "··":
        return carry, -1.9
    if cur in GET_MID:
        if prev.strip() in DECL_WORDS:
            return carry, 0.0
        return carry, -0.85
    if cur in GET_START:
        return carry, -0.45
    if cur == "get":
        return carry, -0.15
    if cur == "\treturn":
        return carry, -0.8
    if cur == " return" or cur == "return":
        if cur == "return":
            return carry, -0.3
        if _is_indent(prev) or prev in (")", ";"):
            return carry, -0.6
        return carry, -0.1
    if cur == " do" and prev in DO_AFTER:
        return carry, -0.65
    if cur == " doing":
        return carry, -0.35
    if cur == " done":
        return carry, -0.2
    if cur in ACTION_VERBS:
        return carry, -0.15
    return carry, 0.0

programs.sol:
"""Recognize exposed -en/-n fragments and German determiner phrases.

German-looking context makes these endings negative; completing ee/oe makes
short fragments positive.  Inflected determiners are more negative after
German prepositions, especially 'in'.  Word frequencies supply only language
clues, not a token lookup table.  Two formatting cases are handled separately.
"""
from functools import lru_cache
import re
from wordfreq import zipf_frequency

READS = ()
POSSESSIVES = {'meinen', 'deinen', 'seinen', 'ihren', 'unseren', 'euren'}
DEMONSTRATIVES = {'diesen', 'jenen'}
PREPOSITIONS = {
    'in', 'unter', 'mit', 'zu', 'an', 'auf', 'aus', 'bei', 'von',
    'zwischen', 'neben', 'hinter', 'vor', 'nach', 'über', 'gegenüber', 'außer'
}

@lru_cache(maxsize=100000)
def german_evidence(word):
    word = word.lower()
    if len(word) < 2:
        return 0.0
    other = max(zipf_frequency(word, language)
                for language in ('en', 'nl', 'sv', 'nb', 'fi', 'fr'))
    return max(-1.0, min(1.0, (zipf_frequency(word, 'de') - other) / 1.5))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0, '', 0)
    _, word, language, previous, position = carry
    raw = prefix.token_strings[-1]
    s = raw.strip().lower()
    joined = bool(word and raw and raw[0].isalpha())
    german = max(0.0, min(1.0, 2 * language + 0.15))
    value = 0.0

    determiner = not joined and (s == 'den' or s in POSSESSIVES
                                 or s in DEMONSTRATIVES)
    if determiner:
        value = 0.28 - 2.56 * german if s == 'den' else -0.93 - 0.81 * german
        if previous.lower() in PREPOSITIONS:
            value -= 2.0
            if previous.lower() == 'in':
                value -= 3.2
            elif previous.lower() == 'unter':
                value -= 2.56
    elif s.isalpha() and 'en' in s:
        strength = 1.0 / max(1, len(s) - 2)
        if not joined and len(s) > 4:
            strength *= 0.25
        if s.startswith('en'):
            value = -1.26 * german
            if s not in ('en', 'ens', 'end', 'ent'):
                value -= 0.5 * german
            continuation = joined and (raw[0].islower() or word[-1:].isupper())
            if continuation and word[-1:].lower() == 'e':
                value += 5.27 - 3.12 * german
            elif continuation and word[-1:].lower() == 'o':
                value += 2.66
        else:
            value = -0.54 * german
        if 'een' in s or 'oen' in s:
            value += 1.5 - 0.73 * max(0.0, zipf_frequency(s, 'en') - 4)
        value *= strength
    elif joined and s in ('n', 'ns', 'nt', 'nn', 'in'):
        if s == 'n' and word.lower().endswith(('e', 'er')):
            value = -2.32 * german
        elif s == 'in':
            value = -0.13 * german
        elif s in ('ns', 'nt', 'nn'):
            value = -0.25 * german
        if any(c in word.lower()[-3:] for c in 'æøå'):
            value += 1.57

    if raw == ':' and previous == 'Title' and position == 1:
        value = -9.37
    if len(raw) > 1 and set(raw) == {'·'}:
        value = -1.0

    for part in re.findall(r'[^\W\d_]+|[^\w]+|\d+|_', raw):
        if part.isalpha():
            word += part
        else:
            if word:
                clue = german_evidence(word)
                if clue:
                    language = 0.9 * language + 0.1 * clue
                previous = word
            if not part.isspace():
                previous = ''
            word = ''
    if raw and raw[-1].isalpha():
        previous = word
    return (doc, word, language, previous, position + 1), float(value)

