"""German oblique '-en' determiners and German word-piece endings, negative.

A word-piece (no leading space, letters only) that ends like a German plural or
dative ending (-n, -en, -nen, -ens, -ent, -end) gets a negative value when the
text around it is German; the German determiner "den" (the dative/accusative
article, strongest after a preposition: "in den", "mit den") is strongly
negative. Everything else is 0."""
from collections import deque

READS = ()

PREPOSITIONS = {" in", " an", " auf", " mit", " zu", " von", " unter", " zwischen", " bei", " nach", " aus", " für", " gegen", " durch", " vor", " über", " um"}
EN_DETERMINERS = {" ihren": -3.6, " seinen": -2.2, " diesen": -4.0, " jeden": -1.7, " allen": -0.2, " einen": -0.4}
GERMAN_WORDS = {"der", "die", "das", "und", "ist", "nicht", "mit", "von", "zu", "auf", "sich", "ein", "eine", "dem", "des", "auch", "wird", "sind", "oder", "wir", "ich", "bei", "nach", "aus", "für", "werden", "sie"}
STRONG_ENDINGS = ("ens", "enn", "ena", "ent", "nen", "end")

def is_german(recent):
    hits = sum(1 for x in recent if x.strip().lower() in GERMAN_WORDS or any(c in "äöüß" for c in x))
    return hits >= 2

def step(carry, prefix, upstream):
    recent = carry if carry is not None else deque(maxlen=40)
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if token == " den":
        value = -4.4 if previous in PREPOSITIONS else -1.3
    elif token in EN_DETERMINERS:
        value = EN_DETERMINERS[token]
    elif token.isalpha() and not token.startswith(" ") and is_german(recent):
        if token.endswith(STRONG_ENDINGS):
            value = -0.9
        elif token.endswith(("n", "ten")):
            value = -0.3
    recent.append(token)
    return recent, value

