"""A local Vietnamese/Thai text feature.

Recent Vietnamese tone-marked vowels or horned vowels enable a larger response
to Vietnamese-like syllables, especially consonant-only syllable beginnings.
Thai letters and marks get a smaller positive response. Ordinary text is near zero. Document starts and repeated middle dots
have separate offsets. These are approximations, not token-identity lookups.
"""
import re
import unicodedata as ud
from functools import lru_cache

READS = ()
ONSETS = frozenset(
    'b c ch d g gh gi h k kh l m n ng ngh nh p ph qu r s t th tr v x'.split()
)
SYLLABLE = re.compile(
    r'(?:ngh|ng|nh|gh|gi|ch|kh|ph|th|tr|qu|[bcdghklmnpqrstvx])?'
    r'[aeiouy]{1,3}(?:ch|ng|nh|[cmnpt])?\Z'
)

@lru_cache(maxsize=8192)
def properties(text):
    s = text.strip()
    n = ud.normalize('NFD', s.lower())
    base = ''.join(c for c in n if ud.category(c) != 'Mn').replace('đ', 'd')
    # Tone-bearing Vietnamese vowels; a bare Romanian-style breve is not enough.
    vietnamese = any(c.lower() in 'ơư' or '\u1ea0' <= c <= '\u1ef9' for c in s)
    thai = any('THAI' in ud.name(c, '') for c in s)
    marks = bool(s) and all(ud.category(c).startswith('M') for c in s)
    ascii_letters = s.isascii() and s.isalpha()
    return s, base, vietnamese, thai, marks, ascii_letters


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    distance = 100 if first else carry[1]
    text = prefix.token_strings[-1]
    s, base, viet, thai, marks, ascii_letters = properties(text)
    syllable = bool(SYLLABLE.fullmatch(base))
    if s == '··' and (first or carry[2]):
        value = 2.65
    elif thai:
        value = .30 if marks else (.58 if len(s) == 1 else .46)
    elif first:
        value = .20 if text[:1].isspace() else .34
    elif distance <= 6:
        # Strongest response just after evidence of Vietnamese text.
        if base in ONSETS:
            if ascii_letters:
                value = 2.20 if text[:1].isspace() else 1.80
            else:
                value = 1.10
        elif syllable:
            value = 1.40 if ascii_letters else .63
        elif not s:
            value = .40
        else:
            value = .18 if len(s) <= 2 else .08
    elif distance <= 31:
        # Weaker language evidence lasts through short unaccented stretches.
        value = .80 if syllable else .25
    else:
        value = -.003
    return (doc, 1 if viet else distance + 1, s == '··'), float(value)

"""Local formatting and lexical approximation, not a complete semantic account.

The largest readable signals are text-encoding damage, context openings,
and Chinese work/activity words versus the ideological suffix '主义' (-ism).
Work and activity signals grow in recent organizational/official language.
Uninterrupted opening runs of carriage returns or double middle dots have
fixed positive values; interior runs do not. Ordinary tokens stay near zero. No vocabulary-ID lookup is used.
"""

import regex
import unicodedata

READS = ()

# File-level declarations and C-family preprocessor directives.
FILE_DECLARATIONS = {'package', 'import', 'using', 'namespace'}
# Common verbs and nouns in Chinese organizational reporting.
ORGANIZATIONAL_LANGUAGE = {
    '加强', '推进', '开展', '落实', '治理', '组织',
    '政府', '干部', '部门', '教育',
}
QUANTIFIERS = {'all', 'any', 'some', 'no', 'many', 'much', 'more',
               'most', 'few', 'less', 'each', 'every', 'both'}


def opening_value(s):
    word = s.strip()
    lower = word.lower()
    value = 0.13 + (0.18 * min(len(word), 12) / 12
                    if word.isalpha() else 0.0)
    if word.isdigit():
        value -= 0.08
    if word and all(unicodedata.category(c)[0] in 'PS' for c in word):
        value -= 0.05
    if regex.search(r'\p{Script=Cyrillic}', word):
        value += 0.16
    if regex.search(r'\p{Script=Han}', word):
        value -= 0.09
    if word.isalpha() and not (word.islower() or word.isupper() or word.istitle()):
        value -= 0.08
    if lower in QUANTIFIERS:
        value += 0.43
    if lower in {'a', 'an'}:
        value += 0.18
    if lower == 'the' and not s.startswith(' '):
        value = -0.25
    if lower in FILE_DECLARATIONS:
        value = -0.60
    if word.startswith('#'):
        value = -0.25
    if word.startswith(('#include', '#if', '#define', '#pragma')):
        value = -0.80
    if word.startswith(('//', '/*')):
        value = -0.55
    if word in {'"', '“', '”'}:
        value = -0.40
    if '\\' in word:
        value += 0.35
    if s == '//\n':
        value = 6.92
    if s == '<|endoftext|>':
        value = 1.31
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    reset = carry is None or carry[0] != doc
    recent = () if reset else carry[1]
    opening_run = None if reset else carry[2]
    previous = recent[-1] if recent else ''
    beginning = not recent or previous == '<|endoftext|>'
    if beginning:
        recent = ()
        opening_run = s if s in {'\r', '··'} else None
    elif s != opening_run:
        opening_run = None
    word = s.strip()
    value = opening_value(s) if beginning else 0.001

    if not beginning:
        if word.endswith(('工作', '活动')):
            context = ''.join(recent)[-80:]
            formal = min(3, sum(context.count(w) for w in ORGANIZATIONAL_LANGUAGE))
            if word.endswith('工作'):  # work, including compounds
                value = 0.40 + 0.55 * formal
            else:                      # activities
                value = 0.17 + 0.22 * formal
        elif word == '所有':            # all / ownership
            value = -0.30
        elif word == '主义':            # doctrines / -isms
            value = -0.80
        elif word == '[' and previous.rstrip().endswith('\\'):
            value = -0.34             # escaped reference brackets
        elif word and set(word) <= set('$£€¥'):
            value = -0.03
        elif word in {',', '.'}:
            value = -0.006

        # UTF-8's C3 lead byte misread as Latin-1 or Windows Cyrillic.
        if word == 'Ã':
            value = 0.75
        elif (word == 'Г' and previous and previous[-1].isascii()
              and previous[-1].isalpha()):
            value = 0.80

    # Large only for uninterrupted runs starting at the context opening.
    # Interior carriage returns, including long runs, stay near zero.
    if opening_run == '\r':
        value = 3.20
    elif opening_run == '··':
        value = 0.41
    return (doc, (recent + (s,))[-32:], opening_run), value

"""Approximate a sparse, signed spelling feature, mainly around letter g.

Internal boundaries matter: G|CD is positive, G|FP negative, and ge|gen
stronger than an unsplit gegen. The rules below cover these abbreviations,
German ge-/st spellings, a few Arabic/Cyrillic joins, and formatting peaks.
They do not explain the component's smaller background fluctuations.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=8192)
def german_word(w):
    return zipf_frequency(w, 'de') > zipf_frequency(w, 'en') + 0.5


def spelling_value(token, previous, old, word, initial):
    s = token.strip()
    low, w, before = s.lower(), word.lower(), old.lower()
    join = bool(old and token and token[0].isalpha())
    if s == '··':
        return -2.89
    if initial:
        formatting = {'\r': -5.38, '\\t': -5.31, '\\n': -2.91,
                      '//\n': -8.25, '\\"': -3.81}
        if token in formatting:
            return formatting[token]
    if not s or not s[-1].isalpha():
        return 0.0

    # Letter-name abbreviations and the algal word family.
    if w == 'gcd':
        return 4.2 if join else 2.7
    if s == 'GD':
        return 2.6
    if s == 'GFP':
        return -2.7
    if s == 'FP' and join:
        if previous.rstrip().endswith(('G', 'Y', 'L')):
            return -4.6
        if old.isupper() and len(old) <= 4:
            return -3.5 if old.endswith(('S', 'R')) else -1.4
    if join and before.endswith('g') and s in ('QL', 'FG'):
        return -3.2 if s == 'QL' else -2.0
    if w in ('algae', 'algal'):
        return -5.8 if w == 'algae' else -8.5
    if join and w == 'ngay':
        return 4.7

    # Comparable short letter groups in Arabic and Cyrillic text.
    if s in ('بعد', 'تعد', 'عد'):
        return 3.1 if s == 'عد' else 4.2
    if join and before.endswith('ع') and s.startswith('د'):
        return 4.0
    if join and before.endswith('ج') and s == 'د':
        return 3.7
    if join and before.endswith('г') and low.startswith('д'):
        return 2.3

    if len(low) > 6:
        return 0.0
    # German stems: stronger when a new piece continues the spelling.
    if w.endswith('gegen'):
        return 4.4 if join else 1.5
    if w.endswith('gelegen'):
        return 2.5
    if w.endswith(('geht', 'gehen', 'ging', 'gering', 'gerade')):
        if german_word(w):
            return 3.8 if join else 2.1
    if low == 'ged' and s[0].isupper():
        return 2.9
    if low == 'gest':
        return 1.1
    if low in ('gen', 'ger', 'ged', 'geh'):
        return 0.33
    if w.endswith('erst') and german_word(w):
        return 3.0 if join else 1.8
    if not join:
        return -1.9 if low == 'gard' else 0.0
    if low == 'ge' and before.endswith(('ent', 'auf', 'mit')):
        return 1.5
    if before.endswith('ge') and low in ('he', 'hen', 'ht'):
        return 4.5 if low == 'he' else 3.0
    if low == 'st' and before.endswith('ng') and german_word(w):
        return 4.5
    if before == 'g' and low.startswith('ing') and german_word(w):
        return 4.3
    if before.endswith('g'):
        if re.fullmatch(r'ed(?:e|en)?', low):
            return 2.8
        if low == 'd':
            return 1.4
        if low in ('sg', 'sv'):
            return 2.4
        if low == 'en' and before.endswith('aug'):
            return 1.2
    if re.fullmatch(r'ug[aegr]?', low) and before in ('a', 'e', 'g'):
        return -2.0
    if low == 'gard':
        return -1.9
    if len(low) <= 4 and low.startswith('ard') and before.endswith(('a', 'g')):
        return -1.6
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', True)
    _, previous, word, initial_run = carry
    initial = not previous or (initial_run and token == previous)
    tail = re.search(r'[^\W\d_]+\Z', word + token)
    new_word = tail.group()[-40:] if tail else ''
    value = spelling_value(token, previous, word, new_word, initial)
    return (doc, token, new_word, initial), value

"""Estimate value-introducing grammatical relations, especially in technical text.

Negative pulses mark copulas, result-producing verbs, and assignment phrases.
Math notation, digits and nearby result/quantity words strengthen the pulses.
Pronoun subjects and fixed comparisons distinguish weaker constructions.
The estimate deliberately omits most small token-specific background effects.
Memory is bounded to 32 preceding tokens and resets with each document.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
COPULAS = set('is are am was were'.split())
PRONOUNS = set(
    'i you he she it we they this that these those there who what '
    'someone everyone nothing something'.split()
)
RESULTS = set(
    'answer result solution sum product difference ratio rate median mean '
    'average probability exponent coordinate coordinates value values '
    'total remainder'.split()
)
ASSIGN = set(
    'set assign assigned setting define defined denote denoted rename '
    'renamed change changed convert converted default defaulted reset '
    'resetting'.split()
)
CHANGE = set(
    'increase increased decrease decreased reduce reduced multiply '
    'multiplied divide divided rotate rotated shift shifted replace '
    'replaced'.split()
)
FIXED_AS = set('such well same long far soon much many early late'.split())
FUNCTIONS = set('and or but if when then so however because since whether'.split())
VERB_ROOTS = {
    'get': 'get', 'give': 'give', 'become': 'become', 'equal': 'equal',
    'return': 'return', 'print': 'return', 'output': 'return',
    'produce': 'return',
}

@lru_cache(maxsize=16000)
def verb_group(word):
    for root in wordnet.base_forms(word, 'verb'):
        if root in VERB_ROOTS:
            return VERB_ROOTS[root]
    return VERB_ROOTS.get(word)

PREPOSITIONS = set('at of by from with into to'.split())

@lru_cache(maxsize=16000)
def categories(word):
    return wordnet.categories(word)


@lru_cache(maxsize=16000)
def is_quantity(word):
    return wordnet.is_a(word, 'quantity')


def predict(token, history):
    cur = token.strip().lower()
    if token == ' ':
        cur = ' '
    eligible = token.startswith(' ') or not cur.isalpha()
    if not eligible:
        return 0.0
    active = COPULAS | PREPOSITIONS | {'be', 'as', 'to', ' ', '==', '===', '!=', '!=='}
    group = verb_group(cur) if cur not in active else None
    if cur not in active and group is None:
        return 0.0

    text = ''.join(history)
    words = re.findall(r'[A-Za-z]+|[0-9]+', text)
    prev = words[-1].lower() if words else ''
    recent = {w.lower() for w in words[-8:]}
    end = history[-1].strip() if history else ''
    math = any(c in text[-100:] for c in '=$^∑∫→')
    digits = min(1.0, sum(c.isdigit() for c in text[-100:]) / 10)
    quantity = bool(recent & RESULTS)
    assigning = bool(recent & ASSIGN)
    changing = bool(recent & CHANGE)
    comma = text.rstrip().endswith(',')

    if cur in COPULAS:
        if prev in PRONOUNS or prev in FUNCTIONS or comma:
            return 0.0
        value = -0.52 - 0.64*math - 0.33*digits - 0.62*quantity
        value -= 0.64*(prev in RESULTS)
        value -= 0.23*('noun.quantity' in categories(prev))
        value -= 0.5*(is_quantity(prev) and prev not in RESULTS)
        value -= 1.5*(prev == 'answer')
        value += 0.27*(cur in {'are', 'were'})
        value += 0.20*(cur in {'was', 'were'})
        return value
    if cur == 'be':
        if prev in {'can', 'may'}:
            return 0.0
        value = -0.34 - 0.67*math - 0.50*digits - 0.56*quantity
        value -= {'should': 0.89, 'would': 0.67, 'must': 0.51,
                  'to': 0.13}.get(prev, 0.0)
        return value
    if cur == 'as':
        if prev in FIXED_AS or comma:
            return 0.0
        value = -0.28 - 0.40*math - 0.34*digits - 0.67*assigning
        value -= 0.50*('verb.communication' in categories(prev))
        value -= 0.27*('verb.creation' in categories(prev))
        if prev in {'written', 'expressed', 'defined', 'denoted', 'represented'}:
            value -= 0.7
        return value
    if cur == 'to':
        return (-1.5*assigning - 0.6*(prev in ASSIGN)
                - 0.42*changing - 0.51*(prev in CHANGE)
                - 0.27*any(c in text[-100:] for c in '`{};'))
    if cur == ' ':
        return (-0.07 - 1.0*(prev in COPULAS or prev == 'be')
                - 0.47*(prev in PREPOSITIONS)
                - 0.30*(end in {'=', '==', '==='})
                - 0.19*(end == ':') - 0.18*quantity)
    if cur == 'by':
        return -0.08 - 0.74*changing - 0.2*math - 0.7*(prev == 'given')
    if cur == 'with':
        return -0.67*changing - 0.65*(prev in CHANGE)
    if cur == 'at':
        return -0.10 - 0.8*(prev in {'valued', 'priced', 'starting'})
    if cur in {'of', 'from', 'into'}:
        return 0.0
    if cur in {'==', '===', '!=', '!=='}:
        return -0.30
    if group == 'become':
        return -0.6 - 0.9*(cur == 'becomes') - 0.62*math - 0.49*digits
    if group == 'return':
        return (-0.12 - 1.1*cur.endswith('s') - 0.45*(prev == 'should')
                - 0.30*(end in {')', ']', '}'}))
    if group == 'give':
        return -0.15 - 0.55*(cur == 'gives') - 0.35*math - 0.20*digits
    if group == 'get':
        return -0.27 - 0.21*math - 0.26*digits - 0.3*(prev in PRONOUNS)
    return -0.50 - 0.25*math - 0.24*digits


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else []
    token = prefix.token_strings[-1]
    value = predict(token, history)
    return (doc, (history + [token])[-32:]), float(value)

