"""layers.1.mlp.down_proj:428: the "value is coming" copula detector.

The component is negative on a word that introduces a value, a definition or an assigned
result: "is" / "be" / "as" / "was" after a quantity noun or a modal ("the answer is", "Default
is", "would be"), "to" after an assignment verb ("set the width to", "rounded to"), "as" after
"defined" / "written", and the space before a number after a quantity noun ("code ", "index ").
It is mildly negative on other copulas and result verbs ("equals", "becomes", "returns"), and
near zero after pronouns and "can/may" ("it is", "he was", "can be"), and in prose. Magnitudes
are group means measured on training text. The big negatives are the rare, strong cases.
"""

READS = ()

# Verbs whose object is a value or expression: "set X to", "defined as", "rounded to".
ASSIGN_VERBS = {'set', 'sets', 'setting', 'changed', 'change', 'changing', 'rounded', 'round',
                'reduced', 'modified', 'updated', 'converted', 'equal', 'equals', 'estimated',
                'decreased', 'increased', 'rename', 'renamed', 'replaced', 'assigned', 'defaulted',
                'adjusted', 'simplified', 'evaluated', 'rounds', 'reduces', 'changes', 'defined',
                'written', 'expressed', 'represented', 'denoted', 'given'}
# Verbs that state what something evaluates to or returns.
RESULT_VERBS = {'equals', 'equal', 'becomes', 'become', 'returns', 'return', 'gives', 'approaches',
                'reaches', 'assign', 'outputs', 'output', 'got', 'get', 'remains'}
COPULA = {'is', 'be', 'was', 'are', 'were', 'as', 'being', 'been'}
# Nouns for quantities and answers: "the answer is", "the sum is", "the default is".
VALUE_NOUNS = {'answer', 'product', 'sum', 'number', 'value', 'default', 'result', 'total',
               'slope', 'length', 'code', 'index', 'output', 'name', 'point', 'distance', 'area',
               'difference', 'midpoint', 'average', 'width', 'height', 'radius', 'velocity',
               'location', 'option', 'counter', 'size', 'count', 'score'}
