NOT_VALUE = {'it', 'this', 'that', 'there', 'what', 'who', 'he', 'she', 'they', 'we', 'i', 'you',
             'can', 'may', 'might'}
MATH_CHARS = set('=+-*/^()<>%$\\{}[]_')


def is_math(s):
    s = s.strip()
