"""A reset response, plus a weak lexical/token-boundary response.

Starts of documents (and initial identical-token runs) are positive.
Later word tokens are mildly negative, especially two-character Han tokens.
A frequent Chinese word overlapping the previous token's end is positive;
its strength depends on that word's frequency relative to the final character.
This approximates, but substantially underestimates, the rare large peaks.
"""
from functools import lru_cache
from math import log10, exp
import regex
import opencc
from wordfreq import get_frequency_dict

READS = ()
HAN = regex.compile(r'\p{Script=Han}+')
SIMPLIFY = opencc.OpenCC('t2s')
EN = get_frequency_dict('en')
ZH = get_frequency_dict('zh')

@lru_cache(maxsize=65536)
def properties(s):
    w = s.strip()
    han = bool(HAN.fullmatch(w))
    latin = w.isascii() and w.isalpha()
    word = any(c.isalpha() for c in w)
    frequency = log10(EN.get(w.lower(), 1e-9)) + 9 if latin else 0
    return w, han, latin, word, frequency

@lru_cache(maxsize=65536)
def overlap(previous, current):
    if len(current) != 1 or len(previous) < 2:
        return 0.0
    if not HAN.fullmatch(previous + current):
        return 0.0
    # Particles, negation and ordinal marking make other boundaries plausible.
    if any(c in previous for c in '的一第不'):
        return 0.0
    p, c = SIMPLIFY.convert(previous), SIMPLIFY.convert(current)
    if ZH.get(p+c, 0) >= 1e-6:  # The whole span is already frequent.
        return 0.0
    pair = ZH.get(p[-1]+c, 0)
    if not pair:
        return 0.0
    relative = log10(pair / ZH.get(c, 1e-9))
    return 0.16 * max(0.0, min(3.0, relative + 2.0))


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, previous, first, initial = 0, '', token, True
    else:
        _, pos, previous, first, initial = carry
        initial = initial and token == first
    w, han, latin, word, frequency = properties(s)
    length = min(len(w), 16)
    spaced = word and s.startswith(' ')
    special = s.startswith('<|') or s.startswith('</tool_')
    if initial:
        value = 0.522 - 0.0095*length
        if word:
            value += 0.426 - 0.121*spaced - 0.0065*frequency
            value += 0.177*w.isupper()
            if han:
                value -= 0.124 if length == 1 else 0.215 if length == 2 else 0
            elif not latin:
                value -= 0.088
        elif w.isdecimal():
            value += 0.239
        if special:
            value = 1.26
        elif s.isspace():
            value = 0.161 if s == ' ' else 0.51
    else:
        value = -0.0019 - 0.003*length - 0.024*exp(-pos/12)
        if word:
            value += -0.0124 - 0.0116*spaced + 0.0027*frequency
            value -= 0.0133*w.isupper()
            if han:
                value += 0.004 if length == 1 else -0.024 if length == 2 else 0.0097
            elif not latin:
                value += 0.0158
        elif w.isdecimal():
            value -= 0.003
        elif s.isspace():
            value -= 0.0052
