READS = ()


def predict(previous, token):
    before = previous.lower()
    s = token.strip().lower()
    joined = not token[:1].isspace()

    # Completing a turn-like spelling across a token boundary.
    if joined and before.endswith('t'):
        if re.fullmatch(r'(?:urn(?:s|ing|ed)?|ourn|umn)', s):
            return -11.0
        # Quantum is an unresponsive counterexample to the split-tum rule.
        if re.fullmatch(r'ums?', s) and not before.endswith('quant'):
            return -8.2 if re.search(r'\bt$', before) else -3.4
        if re.fullmatch(r'un(?:n|ing)?', s):
            return -2.5
        if re.fullmatch(r'ur[bcdfghjklmnpqrstvwxyz]*', s):
            return -1.0
    if joined:
        if before.endswith('tourn') and token.isalpha():
            return -3.0
        if before.endswith(('turn', 'tumn')) and re.fullmatch(
                r'(?:s|ed|ing|ings|er|ers|i|us)', s):
            return -7.6

