        return -4.0 if token.strip()[:1].isupper() else -0.7
    return {
        'turned': -6.8, 'turns': -6.2, 'turning': -7.2, 'turner': -7.7,
        'tur': -1.9, 'tum': -3.5,
        'return': -0.08, 'returned': -1.2, 'returning': -0.9, 'returns': -0.2,
    }.get(s, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = predict(previous, token)
    return (doc, (previous + token)[-80:]), value

