"""Turn-word detector.

The component reads the word being spelled out so far (the letters of the
current word, across subword tokens). It goes strongly negative when that word
is 'turn' or a form of it (turn, turned, turning, turns, Turner, ...), and
weakly negative for near-misses ('tuned', 'tuning', 'retourné'). 'return' and
'tournament' are not turn words and stay at zero. The verb use ('to turn',
'would turn') is stronger than the noun use ('the turn', 'Bob's turn'), and the
idiom 'in turn' is weak. Also a small positive response to 'troy'.
"""
READS = ()

CORE = {"turn": -7.0, "turns": -7.0, "turned": -7.0, "turning": -7.0,
        "turner": -7.0, "turners": -7.0, "turnings": -6.0}
FRAGMENTS = {"tur", "tun", "tum", "tuned", "tuning", "tuner", "urn"}
EXCLUDED_PREFIXES = ("re", "sa", "noc", "spur")
VERB_CUES = {"to", "would", "could", "can", "will", "should", "must", "may", "might",
             "i", "we", "you", "they", "he", "she", "it"}
NOUN_CUES = {"the", "a", "an", "my", "his", "her", "your", "their", "its", "our", "this",
             "that", "s"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, previous, last_doc = carry if carry is not None else ("", "", None)
    if doc != last_doc:
        word, previous = "", ""
    token = prefix.token_strings[-1]
    letters = "".join(ch for ch in token if ch.isalpha()).lower()
    if not letters:
        if word:
            previous = word
        word = ""
    elif word and token[:1].isalpha():
        word = word + letters
    else:
        if word:
            previous = word
        word = letters

    if word in CORE:
        value = CORE[word]
        if word.startswith("turn") and len(word) <= 7:
            if previous in VERB_CUES:
                value = -8.0
            elif previous in NOUN_CUES:
                value = -5.0
            elif previous == "in":
                value = -2.0
    elif word in FRAGMENTS:
        value = -2.0
    elif word.startswith("ret") and "ourn" in word:
        value = -4.0
    elif word.endswith("turn") and not word.startswith(EXCLUDED_PREFIXES):
        value = -4.0
    elif word == "troy":
        value = 2.0
    else:
        value = 0.0
    return (word, previous, doc), value

