READS = ()


def initial_value(text):
    if text == '<|endoftext|>':
        return 2.662
    word = text.strip()
    return (0.206 + 0.023 * min(len(word), 12)
            + 0.054 * text[:1].isspace() - 0.279 * text.isspace()
            + 0.266 * ('\n' in text) + 0.171 * word.isdigit()
            + 0.062 * word.istitle() - 0.126 * word.isascii()
            - 0.300 * text.startswith('<'))


