    doc = prefix.document_ids[-1]
    text = prefix.token_bytes[-1].decode('utf-8', errors='replace')
    fresh = carry is None or carry[0] != doc
    if fresh:
        position, last_break, first_line = 0, 0, True
        previous, initial = '', text
    else:
        _, position, last_break, first_line, previous, initial = carry
        position += 1

    line_break = '\n' in text or '\r' in text
    if fresh:
        value = initial_value(text)
    elif position == 1 and initial == 'Title' and text == ':':
        value = -22.292
    elif text == '<|endoftext|>':
