        value = -0.12
    elif text in ('<tool_call>', '<tool_response>'):
        value = 0.09
    elif text == '</tool_call>':
        value = 0.25
    elif text == '</tool_response>':
        value = -0.07
    elif text == '</think>':
        value = -0.12
    elif text in ('<|im_start|>', '<|im_end|>'):
        value = 0.05
    else:
        value = 0.0

