        return 1.566
    if token in EMPTY_COMMENT_LINES:
        return EMPTY_COMMENT_LINES[token]
    if token in {'public', 'private'}:
        return -2.3
    if token in {'protected', 'static'}:
        return -0.55
    if token in {'def', 'function'}:
        return -1.1
    if token in {'int', 'void'}:
        return -1.0
    if token == 'export':
        return -1.62
    if token == '//':
        return -0.37
    if token.startswith('/*'):
        return 0.22
    word = token.strip()
    if word.lower() in POSSESSIVES:
        return 0.8
    if token in {'The', 'A', 'An'}:
        return -0.33
    if word.lower() in FUNCTION_WORDS:
        return -0.10
    if token == '\t':
        return 0.74
    if token.isspace():
        return -0.25 if '\n' in token else -0.08
    if word.isdecimal():
        return 0.13
    if regex.search(r'\p{Script=Cyrillic}', token):
        return 0.38
    if not token.isascii():
        return 0.22
    return 0.15 if word.isalpha() else 0.04


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        position, first, repeated = 0, token, True
    else:
        _, position, first, repeated = carry
        position += 1
        repeated = repeated and token == first

    value = opening(first) if repeated else 0.0
    if position == 1:
        if first == 'Title' and token == ':':
            value = 2.83
        elif first == '{' and token == '[':
            value = -3.106
        elif first in {'//\n', '//\r\n'} and token == '//':
            value = -0.52
        elif first in {'#\n', '#\r\n'} and token == '#':
            value = -0.28
    return (document, position, first, repeated), value

programs.haiku:
"""Document-start readout of one MLP-down component (layer 1, unit 443).

What it responds to: almost nothing. Its activation is about 0 at nearly every token,
but the first token of each document (the model resets attention and position there)
gets a value fixed by that token's kind. The program predicts that value at document
starts, the large value for the colon in a "Title:" header, and 0 elsewhere.
"""
READS = ()

PREP_WH = {"of", "to", "for", "in", "on", "at", "with", "from", "by", "after", "before",
           "what", "who", "how", "why", "when", "where", "which"}
PRONOUNS = {"i", "my", "your", "his", "her", "our", "their", "me", "we", "you"}

def doc_start_value(s):
    word = s.strip().lower()
    if s == "//\n":
        return -5.2                     # a document opening with a bare comment line
    if s.startswith("//"):
        return -0.4                     # other comment-line starts
    if "\n" in s and not word:
        return -0.25                    # a document opening with a line break
    if word in PREP_WH:
        return -0.25                    # prepositions and question words
    if word in PRONOUNS or word.isdigit():
        return 0.2                      # pronouns and numbers
    if any(ord(c) > 127 and c.isalpha() for c in s):
        return 0.3                      # non-Latin scripts
    return 0.1

def step(carry, prefix, upstream):
    docs, s = prefix.document_ids, prefix.token_strings
    starts_doc = prefix.position == 0 or docs[-1] != docs[-2]
    if starts_doc:
        return None, doc_start_value(s[-1])
    # second token of a document is a colon right after a document-initial "Title"
    if s[-1] == ":" and s[-2] == "Title" and (prefix.position == 1 or docs[-3] != docs[-2]):
        return None, 2.8
    return None, 0.0

programs.sol:
"""Sparse local spelling effects, chiefly around e/ex token boundaries.

Negative examples include exile, exemption, exclusion, exchange and
exudation; positive ones include example- and execution-like spellings.
A few e/ed, dye and mathematical-expectation spellings are also covered.
These are spelling rules, not a semantic classifier. Values are conservative
training-based estimates; unrecognized positions are zero.
"""
READS = ()


def activation(previous, token):
    p, s = previous.lower(), token.lower()
    word = s.strip()
    if s.startswith(' '):
        if word in ('exile', 'exiles', 'exiled'):
            return -0.93
        if word.startswith('exempt'):
            return -1.08
        if word.startswith('exclusion'):
            return -0.76
        if word == 'edible':
            return -0.26
        return 0.0
    if p.endswith('ex'):
        if s.startswith('ud'):                  # exudation
            return -2.47
        if s.startswith('il'):                  # exile
            return -2.08
        if s.startswith(('cl', 'kl')):          # exclusion
            return -1.59
        if s.startswith('ch'):                  # exchange
            return -2.0
        if s.startswith('empt'):                # exemption
            return -1.59
        if s.startswith(('ec', 'éc')):          # execution
            return 2.09
        if s.startswith(('ampl', 'empl')):      # example
            return 1.36
        if p.endswith('hex') and s.startswith('a'):
            return 0.41
    if p.strip() in ('es', 'ej') and s.startswith('emp'):
        return 1.36                             # Italian/Spanish examples
    if p.endswith('extr') and s.startswith('ud'):
        return -1.28                            # extrusion
    if p.strip() == 'e':
        if s.startswith('(x'):
            return 0.60                         # expectation E(X)
        if s.startswith('ch'):
            return -2.0
        if s.startswith('quest'):
            return -2.19                        # equestrian
        if s.startswith('ddy'):
            return -1.95
        if s.startswith(('el', 'gest')):
            return -1.35
    if p.strip() == 'ed' and s.startswith(('el', 'ib', 'il', 'g', 'ch')):
        return -1.57
    if p.strip() == 'd' and s.startswith('ye'):
        return -1.95                            # dye / Dyer
    return 0.0


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    return None, activation(prefix.token_strings[-2], prefix.token_strings[-1])

"""Local cues for problems, their causes, and uncertain explanations.

Negative values mark problem/error vocabulary and linking phrases, especially
'problem is that', 'issues with', and 'may be due to'. Weaker cues include
uncertainty, existential 'there', and 'my'. English inflections come from
WordNet; Chinese problem/cause cues come from dictionary glosses. This is a
five-token local approximation, not a general sentiment classifier. Positive
variation and responses outside these cases are not modelled.
"""
from functools import lru_cache
import wordnet
import wordfreq
import cedict
import regex

READS = ()
# Semantic class: (root words, activation strength).
CLASSES = {
    'issue': ('issue', -1.1),
    'problem': ('problem', -0.25),
    'fault': ('mistake bug', -1.1),
    'error': ('error erroneous', -0.5),
    'difficulty': ('difficulty trouble obstacle barrier limitation challenge', -0.6),
    'defect': ('defect flaw mismatch inconsistency discrepancy anomaly glitch', -0.9),
    'cause': ('cause reason', -0.5),
    'source': ('source origin factor', -0.3),
    'effect': ('result consequence lead arise occur happen emerge persist',
               -0.15),
    'concern': ('concern worry risk danger delay failure fail fix', -0.35),
    'lack': ('lack shortage', -0.65),
    'negative': ('confused inconsistent problematic difficult poor', -0.3),
    'other_negative': ('', -0.15),
    'chinese_problem': ('', -0.65),
    'chinese_cause': ('', -0.4),
}
ROOT_CLASS = {w:c for c,(words,_) in CLASSES.items() for w in words.split()}
ADVERSE = set(CLASSES) - {'cause', 'source', 'effect', 'chinese_cause'}
FUNCTIONS = {'may': -0.5, 'might': -0.65, 'could': -0.12,
             'maybe': -0.15, 'perhaps': -0.15, 'because': -0.5,
             'due': -0.8, 'there': -0.43, 'my': -0.37, 'why': -0.47,
             'potential': -0.3, 'potentially': -0.3, 'possibility': -0.3}
LINKS = set('is was be are were been being seems appears'.split())
MODALS = set('may might could can will would should shall must'.split())
ADVERSE_PREPS = {'with': -0.65, 'in': -0.65, 'of': -0.33, 'about': -0.6}
CAUSAL_PREPS = {'by': -0.35, 'for': -0.55, 'from': -0.8,
                'in': -0.4, 'of': -0.55, 'to': -0.45}


@lru_cache(maxsize=65536)
def roots(w):
    return wordnet.base_forms(w) if w.isascii() and w.isalpha() else (w,)


@lru_cache(maxsize=65536)
def category(w):
    for root in roots(w):
        if root in ROOT_CLASS:
            return ROOT_CLASS[root]
    if regex.search(r'\p{Script=Han}', w):
        w = w.removeprefix('的').removeprefix('是').removesuffix('着')
        pieces = [w] + [w[i:i+2] for i in range(len(w)-1)]
        gloss = ' '.join(g for p in pieces for g in cedict.glosses(p)).lower()
        if regex.search(r'\b(problem|difficulty|trouble)\b', gloss):
            return 'chinese_problem'
        if regex.search(r'\b(cause|because|reason)\b', gloss):
            return 'chinese_cause'
    elif w.isalpha() and w.isascii() and wordfreq.zipf_frequency(w, 'en') < 4.2:
        if any(wordnet.is_a(w, k) for k in ('error', 'difficulty', 'disadvantage')):
            return 'other_negative'
    return ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, h = carry if carry is not None else (None, ())
    if doc != old_doc:
        h = ()
    raw = prefix.token_strings[-1]
    w = raw.strip().lower()
    p = h[-1] if h else ''
    c, pc = category(w), category(p)
    if c == 'issue' and (
        w not in {'issue', 'issues'} or p in MODALS | {'to', 'simply', 'please'}
    ):
        c = ''  # 'issue a command' is not a problem noun.
    value = CLASSES[c][1] if c else FUNCTIONS.get(w, 0.0)
    if w == 'may' and raw.strip() != 'may':
        value = 0.0  # Not the month May.
    if c.startswith('chinese_') and len(w) == 1:
        value *= 0.5  # A single Han character is a less specific lexical cue.
    if c and not raw.startswith(' ') and not c.startswith('chinese_'):
        value += 0.1

    # Nouns followed by their locus/cause, or by an explanatory complement.
    if pc in ADVERSE:
        value += ADVERSE_PREPS.get(w, 0.0)
    elif pc in {'cause', 'source', 'effect'}:
        value += CAUSAL_PREPS.get(w, 0.0)
    if w == 'with' and pc in {'issue', 'problem', 'difficulty'}:
        value -= 1.9
    if w == 'in' and pc in {'error', 'fault'}:
        value -= 1.05
    if w in LINKS and pc in ADVERSE:
        value -= 0.6 + (0.5 if pc == 'issue' else 0.0)
    if w == 'that' and len(h) >= 2 and p in LINKS:
        if category(h[-2]) in ADVERSE:
            value -= 3.9 + (1.3 if category(h[-2]) == 'issue' else 0.0)

    # Causal and uncertain frames.
    if w == 'to' and p == 'due':
        value -= 1.05 + (1.2 if len(h)>1 and h[-2]=='be' else 0.0)
    if w == 'due' and p == 'be':
        value -= 0.75 + (1.6 if any(x in MODALS for x in h) else 0.0)
    if w in LINKS and p in {'may', 'might', 'could'}:
        value -= 0.4 + (0.5 if p == 'might' else 0.0)
    if w == 'of' and p == 'because':
        value -= 0.6
    if w in {'the', 'a'} and p in {'maybe', 'perhaps'}:
        value -= 0.4
    if w == 'there' and p in {'to', 'from', 'out', 'over', 'right', 'back'}:
        value += 0.36
    if w == 'by' and set(roots(p)) & {'complicate', 'limit', 'affect', 'influence'}:
        value -= 0.7
    if w == 'from' and set(roots(p)) & {'stem', 'come', 'suffer', 'struggle'}:
        value -= 0.8
    if w == 'lead' and p in MODALS:
        value -= 0.9

    # Distinguish 'a problem' from a routine reference to a maths problem.
    if c == 'problem':
        value -= 0.7 if p in {'a', 'an'} else 0.0
        value -= 0.25 if w == 'problems' else 0.0
    if c == 'issue' and p in {'a', 'an', 'any'}:
        value -= 1.1
    if c in {'issue', 'problem', 'error', 'cause'}:
        if any(x in {'may', 'might', 'could', 'there', 'possible', 'potential'}
               for x in h):
            value -= 1.3
        if p in {'root', 'underlying', 'main', 'major', 'serious', 'common'}:
            value -= 1.2
    return (doc, (h + (w,))[-5:]), value

programs.haiku:
"""Problems and their causes. The activation goes negative on words that name a problem
(issue, mistake, bug, error, problem, trouble, risk, concern, difficulty ...) and on words
that name a cause, result or sign (due, because, cause, reason, result, leads ...), and on
hedges (may, might, could, perhaps). The strongest cases are "issue", "mistake", "due" and
"reason(s)". The linking word right after such a word ("issue with", "due to", "result of",
"related to") is negative too, most of all after a problem word. Everything else is about 0."""

READS = ()

STRONG = {"issue", "issues", "mistake", "mistakes", "bug", "bugs", "difficulties", "due", "reasons", "causing"}
PROBLEM = {
    "problem", "problems", "error", "errors", "trouble", "challenge", "challenges", "risk",
    "risks", "concern", "concerns", "lack", "flaw", "defect", "obstacle", "obstacles",
    "failure", "fault", "wrong", "difficulty", "threat", "threats", "danger", "conflict",
    "conflicts", "contradiction", "crisis",
}
CAUSE = {
    "because", "cause", "causes", "caused", "reason", "factor", "factors", "why", "owing",
    "lead", "leads", "leading", "led", "result", "results", "resulting", "resulted",
    "consequence", "consequences", "source", "sources", "behind", "sign", "signs", "related",
    "linked", "attributed",
}
HEDGE = {"may", "might", "could", "there", "perhaps", "maybe"}
LINK = {"to", "with", "of", "that", "in", "for", "from", "by", "at", "is", "be", "about", "or"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in STRONG:
        return None, -1.2
    if word in PROBLEM:
        return None, -0.45
    if word in CAUSE:
        return None, -0.25
    if word in HEDGE:
        return None, -0.3
    if word == "my":
        return None, -0.3
    if word in LINK:
        if prev in STRONG or prev in PROBLEM:
            return None, -1.0
        if prev in CAUSE:
            return None, -0.5
        if prev in HEDGE:
            return None, -0.25
    return None, 0.0

programs.sol:
"""A small recognizer for negative quantities and restrictive expressions.

No, neither, none, and scarcity words produce negative values. Local grammar
changes their strength: bare little/few differ from a little/few, and negation
licenses any and even. Some common equivalents in other languages are included.
Double negatives such as non-zero and not None give positive values. This is
an approximate lexical/grammatical account, not a general negation parser.
It retains 200 characters within each document; unrecognized tokens get zero.
"""
import re
import wordnet

READS = ()

NEGATIVE_QUANTIFIERS = {
    'neither': -7.0, 'none': -4.8,
    'nobody': -5.3, 'nothing': -2.3, 'nowhere': -2.8,
    'rarely': -4.0, 'seldom': -4.0,
    'barely': -3.5, 'scarcely': -2.5, 'hardly': -2.0,
    'scant': -2.5, 'only': -0.95, 'minimal': -0.65,
    'nur': -1.05, 'ni': -3.1, 'rien': -3.0,
    'personne': -3.0, 'aucun': -3.7, 'niemand': -5.0,
    'nichts': -2.0, 'geen': -2.5, 'nunca': -1.1,
    'ninguna': -2.7, 'nada': -2.1, 'nary': -5.5,
    'tampoco': -5.0, 'neppure': -4.5, 'nemmeno': -4.5,
}
DETERMINERS = set('the this that these those my your his her its our their'.split())
FRENCH_SUBJECTS = set('je tu il elle on nous vous ils elles ce cela qui'.split())
PORTUGUESE_CUES = set('uma um com dos das ao aos não nosso são mais os'.split())
SPANISH_CUES = set('el los las una del pero por muy'.split())
OBJECT_VERBS = {'verb.perception', 'verb.creation', 'verb.possession'}


def predict(word, token, before, lead, words):
    prev = words[-1] if words else ''
    recent = set(words[-25:])
    piece = re.search(r'([^\W\d_]+)\Z', token)
    capital = bool(piece and piece.group()[0].isupper())
    value = NEGATIVE_QUANTIFIERS.get(word, 0.0)
    # An identifier such as is_none or Category.None is not a quantifier.
    if re.search(r'\w[_.]$', lead):
        return 0.0

    if re.fullmatch(r'kein(?:e[rmns]?|s)?', word):
        return -8.5 if word in ('keiner', 'keins') else -4.3
    if word in ('n', 'ne'):
        if capital:
            return 0.0
        if prev in FRENCH_SUBJECTS:
            return -2.8 if word == 'n' else -2.1
        if word == 'ne' and recent & {'est', 'une', 'pas', 'les', 'dans', 'des'}:
            return -1.9
        return 0.0

    if word == 'nem':
        return -3.1 if recent & PORTUGUESE_CUES else 0.0
    if word == 'no':
        if recent & PORTUGUESE_CUES:
            return 1.1
        if recent & SPANISH_CUES or prev == 'que':
            return -0.2
        if prev in ('le', 'la', 'les', 'un', 'une', 'der', 'die', 'das', 'nel'):
            return 0.0
        if capital:
            if lead.endswith(("'s ", '’s ')):
                return -0.2
            return -1.2 if token.strip().isupper() else -1.5
        if not token.startswith(' '):
            return -1.8 if before else 0.1
        if prev in ('where', 'which', 'that'):
            return -4.8
        if prev in ('and', 'with', 'by', 'in'):
            return -3.9
        if prev in ('of', 'for', 'to', 'are', 'were'):
            return -3.1
        if prev in ('is', 'was', 'be', 'been', 'being', 'has', 'does', 'do'):
            return -2.2
        if prev in ('have', 'had'):
            return -3.0
        if wordnet.categories(prev) & OBJECT_VERBS:
            return -3.9
        if re.search(r'[:\d→]\s*$', lead) or prev == 'wait':
            return -1.2
        return -2.5

    if word in ('few', 'little'):
        if prev == 'a':
            return 0.8 if word == 'few' else 0.25
        if prev in DETERMINERS:
            return -0.5 if word == 'few' else 0.0
        if word == 'few' and prev in ('first', 'last', 'next', 'every', 'extra'):
            return 3.4
        if word == 'few' and prev == 'past':
            return 1.0
        if prev == 'too':
            return -3.0
        if prev in ('very', 'so'):
            if len(words) > 1 and words[-2] in DETERMINERS:
                return -2.5
            return -6.6 if word == 'few' else -5.5
        if word == 'little' and not before:
            return 0.0
        if word == 'little' and prev == 'with':
            return -5.0
        if word == 'little' and len(words) > 1:
            if words[-2] in ('have', 'has', 'had'):
                return -5.2
        if word == 'little' and capital:
            return -1.0
        if word == 'little' and 'adjective' in wordnet.parts_of_speech(prev):
            return -0.4
        if word == 'little' and 'verb' in wordnet.parts_of_speech(prev):
            return -5.2
        return -3.7

    if word == 'couple':
        return 2.8 if prev in ('every', 'last', 'next') else 0.5
    if word in ('one', 'other') and re.search(
        r'\b(?:no|none)\s+\Z', lead, re.IGNORECASE
    ):
        return -3.7 if word == 'one' else -2.3
    if word == 'fewer':
        return 1.9 if prev == 'no' else -1.7
    if word == 'only' and prev in ('not', 'the'):
        return -0.1
    if word in ('any', 'anything', 'anyone', 'anybody', 'even'):
        if prev == 'without':
            return -3.1
        negative = re.search(r"(?:\bnot|n't|n’t)\s*$", lead.lower())
        if negative:
            return -3.2 if word == 'even' else -2.3
        if word == 'any' and prev in ('have', 'has', 'had', 'been'):
            if re.search(r"(?:\bnot|n't|n’t)\s+\w+\s*$", lead.lower()):
                return -2.3
        return 0.3 if word == 'even' else 0.0
    if word == 'never':
        if capital:
            return -2.3
        return -0.4 if prev in ('has', 'have', 'had') else -1.2
    if word == 'nothing' and prev in ('is', 'was', 'has', 'have', 'do'):
        return -0.5 if prev == 'do' else -1.3
    if word == 'none' and capital:
        if prev == 'not':
            return 3.1
        if prev in ('return', 'returns', 'returned') or lead.rstrip().endswith('->'):
            return 1.2
        return -4.0 if re.search(r'(?:[.!?]\s*["“]?|:\s*["“])\s*\Z', lead) else 0.1
    if word == 'nor':
        if capital:
            return -2.0
        return -5.8 if lead.rstrip().endswith((',', ';')) else -4.1
    if word == 'ni' and capital:
        return -1.6
    if word in ('too', 'necessarily'):
        if re.search(r"(?:\bnot|n't|n’t)\s*$", lead.lower()):
            return 1.4 if word == 'too' else 1.0
    if word == 'not' and prev == 'need':
        return -2.0
    if word in ('zero', 'null', 'nil') and prev == 'non':
        return 2.2
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    # Escaped whitespace in quoted text also separates words.
    text = before + token
    for escaped, space in ((r'\n', '\n'), (r'\r', '\r'), (r'\t', '\t')):
        text = text.replace(escaped, space)
    match = re.search(r'([^\W\d_]+)\Z', text)
    value = 0.0
    if match and token and token[-1].isalpha():
        word = match.group().lower()
        lead = text[:match.start()]
        words = re.findall(r"[^\W\d_]+(?:['’]t)?", lead.lower())
        value = predict(word, token, before, lead, words)
    # Training calibration slightly shrinks the local magnitude estimates.
    return (doc, text[-200:]), 0.95 * value
